INSERT INTO `locations` (`id`, `name`, `category`, `primary_show_id`, `sort_order`, `website`, `wikipedia`, `instagram`, `primary_photo`, `primary_photo_thumbnail`, `secondary_photo`, `map_embed_link`, `description`, `taskmaster_connection`, `first_appearance`) VALUES
(1, 'Taskmaster House (UK)', 'house', 1, 1, NULL, NULL, NULL, '001_taskmaster_house_uk.jpg', '001_taskmaster_house_uk_thumb.jpg', NULL, 'https://www.google.com/maps/embed?pb=!1m10!1m8!1m3!1d184.44117087982866!2d-0.266511072607379!3d51.4746403279743!3m2!1i1024!2i768!4f13.1!5e1!3m2!1sen!2suk!4v1699061214098!5m2!1sen!2suk', 'This three-bedroom bungalow in Chiswick, West London, is a former groundskeepers’ cottage, currently owned by the adjacent Dukes Meadows Golf, Tennis and Ski facility.', 'The original Taskmaster house, as featured in the UK version of Taskmaster since 2015.|The property is rented throughout the year by Avalon for production of the show (typically 21 episodes per year).|Over the years, additions have been made to the property by the production team, including a caravan (from series 4), a plastic geodesic dome (from the New Year\'s Treat 2021), a large decked area (from series 13), and a hutch (from series 16).', 'The exterior of the Taskmaster House is first seen in the introductory sequence before the \'<a href=\"/task.php?id=2\">Eat as much watermelon as possible</a>\' task, in the first episode of series 1.'),
(2, 'Dukes Meadows Bandstand', 'other', NULL, NULL, 'https://dukesmeadowstrust.org/', 'https://en.wikipedia.org/wiki/Dukes_Meadows', 'https://www.instagram.com/dukesmeadowspark/', '002_dukes_meadow.jpg', '002_dukes_meadow_thumb.jpg', '002_dukes_meadow_2.jpg', 'https://www.google.com/maps/embed?pb=!1m14!1m12!1m3!1d368.86657530210994!2d-0.25226265192911723!3d51.47659000522525!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!5e1!3m2!1sen!2suk!4v1699127190373!5m2!1sen!2suk', 'Dukes Meadows is a riverside park in Chiswick, London.|The land was bought by the council in 1923, and a seaside-type promenade and a bandstand were built alongside the Thames riverfront and opened by Prince Albert, Duke of York (later King George VI) in 1926.|The park is cared for by the Dukes Meadows Trust, and it is home to the Chiswick Farmers\' Market, which helps to pay for the park\'s maintenance.|From 2023, the Dukes Meadows Footbridge forms part of the Thames Path.', 'The bandstand and adjacent structures have been used occasionally for tasks since the first series of the show.', 'Dukes Meadows Bandstand is first seen in the \'<a href=\"/task.php?id=30\">Make a bed while holding hands</a>\' task, in episode 5 of series 1.'),
(3, 'The Clapham Grand', 'studio', NULL, 1, 'https://claphamgrand.com/', 'https://en.wikipedia.org/wiki/Clapham_Grand', 'https://www.instagram.com/theclaphamgrand/', '003_the_clapham_grand.jpg', '003_the_clapham_grand_thumb.jpg', '003_the_clapham_grand_2.jpg', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d184.48769193452122!2d-0.16958843385732195!3d51.463133681940846!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x48760599f8651293%3A0x2c8222c433208501!2sThe%20Clapham%20Grand!5e1!3m2!1sen!2suk!4v1699131816776!5m2!1sen!2suk', 'The Grand (previously The Grand Theatre) is a Grade II listed building on St John\'s Hill, near Clapham Junction in Battersea, South London.|It was designed by Ernest Woodrow and was first opened in 1900 as The New Grand Theatre of Varieties.|The Grand continued to be a successful Music Hall and Variety venue for 40 years. In 1927, the theatre was fitted for cinema use, but remained known as The Grand Theatre, as it still mainly staged variety shows.|From May 1950, The Grand went on to become a full-time cinema, after it was purchased by the Essoldo Cinema chain, and was renamed Essoldo Cinema.|The Essoldo Cinema closed in August 1963 and became the Essoldo Bingo Club in October 1963. It was later taken over by Classic Cinemas, who renamed it Vogue Bingo Club. During this time, they built a false ceiling, cutting off the upper parts of the theatre.|From 1972 until 1979, Mecca Bingo took over as the final bingo operator. The building then remained closed until 1989 when it was bought by The Mean Fiddler group to be transformed into a live music venue which, due to licensing issues, did not open until December 1991.|During the 10-year closure between 1979 and 1989, the false ceiling was removed, and the building was restored and redecorated.|Mean Fiddler closed in July 1997 after being mostly unsuccessful as a music venue and the venue was then purchased by the pub chain J.D.Wetherspoon, which was then unable to acquire a license to serve alcohol there.|The Grand is now an independently run venue which functions as a nightclub, live music venue, theatre and event space.', 'The theatre was used as the studio location for the first series of Taskmaster, with subsequent series instead using a studio set which replicates the venue\'s interior.', 'The interior of The Clapham Grand is first seen at the start of the <a href=\"/episode.php?id=1\">first episode of series 1</a>.'),
(4, 'Fountain Studios', 'studio', NULL, 2, NULL, 'https://en.wikipedia.org/wiki/Fountain_Studios', NULL, '004_fountain_studios.jpg', '004_fountain_studios_thumb.jpg', '004_fountain_studios_2.jpg', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d363.7414317131207!2d-0.28175921059177067!3d51.56116569128338!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x4876117e12529a41%3A0xe3ef913b6fdd3b0!2sFountain%20Studios%2C%20128%20Wembley%20Park%20Dr%2C%20Wembley%20Park%2C%20Wembley%20HA9%208HP!5e1!3m2!1sen!2suk!4v1699746452446!5m2!1sen!2suk', 'Fountain Studios was an independently-owned television studio located in Wembley Park, northwest London, England.|Several companies owned the site before it was bought by Fountain in 1993. Originally a film studio complex, it was formerly the base for the ITV contractors Rediffusion from 1955 to 1968, and London Weekend Television from 1968 to 1972.|Most recently, the studios were best known for being the venue for the live stages of ITV shows <em>The X Factor</em> and <em>Britain\'s Got Talent</em>.|In January 2016, it was confirmed that the studios had been sold for £16 million to the property development company Quintain.|In May 2018, it was announced that the studios would re-open in the latter half of 2018 as a flexible 1,000- to 2,000-seat theatre run by Troubador Theatres (the same company that owns Wembley Park Theatre Ltd), as well as a bar and restaurant.', 'The studios were used to film the studio segments of series 2 and series 3 of Taskmaster, using a set designed to replicate the appearance of The Clapham Grand, where the first series had been filmed.', 'The interior of Fountain Studios is first seen at the start of the <a href=\"/episode.php?id=7\">first episode of series 2</a>.'),
(5, 'Pinewood Studios', 'studio', NULL, 3, 'https://pinewoodgroup.com/studios/pinewood-studios', 'https://en.wikipedia.org/wiki/Pinewood_Studios', 'https://www.instagram.com/pinewoodstudios/', '005_pinewood_studios.jpg', '005_pinewood_studios_thumb.jpg', '005_pinewood_studios_2.jpg', 'https://www.google.com/maps/embed?pb=!1m14!1m12!1m3!1d727.6790698555234!2d-0.5337798690847706!3d51.54889968124066!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!5e1!3m2!1sen!2suk!4v1699746602849!5m2!1sen!2suk', 'Pinewood Studios is a British film and television studio located in the village of Iver Heath, approximately 18 miles west of central London.|The studio has been the base for many productions over the years from large-scale films to television programmes, commercials, and pop promos, including the <em>James Bond</em> and <em>Carry On</em> film franchises.', 'The studios have been used to film the studio segments of Taskmaster since series 4, using a set designed to replicate the appearance of The Clapham Grand, where the first series had been filmed.', 'The interior of Fountain Studios is first seen at the start of the first episode of <a href=\"/season.php?id=4\">series 4</a>.'),
(6, 'All Saints Pastoral Centre and Chapel', 'other', NULL, NULL, NULL, 'https://en.wikipedia.org/wiki/All_Saints_Pastoral_Centre', NULL, '006_all_saints_pastoral_centre_and_chapel.jpg', '006_all_saints_pastoral_centre_and_chapel_thumb.jpg', '006_all_saints_pastoral_centre_and_chapel_2.jpg', 'https://www.google.com/maps/embed?pb=!1m14!1m12!1m3!1d725.062566031739!2d-0.301147368235893!3d51.712301728137874!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!5e1!3m2!1sen!2suk!4v1699746313114!5m2!1sen!2suk', 'All Saints Pastoral Centre is a complex of buildings at London Colney, on the southern outskirts of St Albans, Hertfordshire, England. It was built as a convent for the Anglican Society of All Saints Sisters of the Poor.|The original buildings were designed by Leonard Stokes in 1899, and built in 1901 with a chapel added in 1927 by Ninian Comper. It was Grade II* listed in 1972.|The complex was acquired by the Roman Catholic Archdiocese of Westminster in 1973, and converted for use as a pastoral centre.|It was sold to a property developer in 2011, with the sale finalised in 2014.|The main structure is built around a garden and has an inner cloister leading to the meeting rooms.|The centre today caters to both residential and non-residential conferences, meetings and retreats mainly from the religious sector.', 'The All Saints Pastoral Centre and Chapel were used for the filming of location-based tasks during series 12 of Taskmaster UK.', 'The location was first seen in the \'<a href=\"/task.php?id=1245\">Pop the balloon</a>\' task, in the first episode of series 12.'),
(7, 'Barn Elms Sports Trust', 'other', NULL, NULL, 'https://www.bestfields.co.uk/', NULL, 'https://www.instagram.com/bestfields/', '007_barn_elms_sports_trust.jpg', '007_barn_elms_sports_trust_thumb.jpg', '007_barn_elms_sports_trust_2.jpg', 'https://www.google.com/maps/embed?pb=!1m14!1m12!1m3!1d728.8801583420873!2d-0.23302589667712417!3d51.473767105300546!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!5e1!3m2!1sen!2suk!4v1699746100086!5m2!1sen!2suk', 'Barn Elms Sports Trust (known locally as BEST) is a registered charity dedicated to the management of the sporting provision on the Barn Elms Playing Fields, a London Borough of Richmond-upon-Thames owned site.|Facilities managed by the trust include a 400m running track, 100m sprint track, facilities for high jump, long jump, javelin and shot put, tennis courts, seasonal pitches for football, rugby, cricket and rounders, and a pavilion containing changing rooms, showers, toilets, and a café.', 'Barn Elms Sports Trust was used for the filming of location tasks in series 3 of Taskmaster UK.', 'The location was first seen in the \'<a href=\"/task.php?id=67\">Reach the microwave in the fewest steps</a>\' task, in the first episode of series 3.'),
(8, 'Barnes Hockey Club', 'other', NULL, NULL, 'https://www.barneshockeyclub.co.uk/', 'https://en.wikipedia.org/wiki/Barnes_Hockey_Club', 'https://www.instagram.com/barneshockeyclub/', '008_barnes_hockey_club.jpg', '008_barnes_hockey_club_thumb.jpg', '008_barnes_hockey_club_2.jpg', 'https://www.google.com/maps/embed?pb=!1m14!1m12!1m3!1d728.8940290146361!2d-0.2585166755622886!3d51.472898984940855!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!5e1!3m2!1sen!2suk!4v1699745991565!5m2!1sen!2suk', 'Barnes Hockey Club is a field hockey club based at Duke\'s Meadows, Chiswick, West London and was formed in 1889.|The club has both men\'s and women\'s sections, with four teams for men and seven for women, in addition to a junior section.', 'Barnes Hockey Club was used for some team-based location tasks during series 13 of Taskmaster UK.', 'The location was first seen during the \'<a href=\"/task.php?id=1897\">Score an exercise ball hat-trick using a buggy</a>\' task, in the second episode of series 13.'),
(9, 'Buckinghamshire Railway Centre', 'other', NULL, NULL, 'https://www.bucksrailcentre.org/', 'https://en.wikipedia.org/wiki/Buckinghamshire_Railway_Centre', 'https://www.instagram.com/bucksrailcentre/', '009_buckinghamshire_railway_centre.jpg', '009_buckinghamshire_railway_centre_thumb.jpg', '009_buckinghamshire_railway_centre_2.jpg', 'https://www.google.com/maps/embed?pb=!1m14!1m12!1m3!1d722.6204406572689!2d-0.9278694036237671!3d51.86448250689196!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!5e1!3m2!1sen!2suk!4v1699746808187!5m2!1sen!2suk', 'Buckinghamshire Railway Centre is a railway museum operated by the Quainton Railway Society Ltd. at Quainton Road railway station, about 5 miles west of Aylesbury in Buckinghamshire.|The site is divided into two halves which are joined by two foot-bridges. Each side has a demonstration line with various workshop buildings as well as museum buildings.|The centre houses around 170 items of locomotives and rolling stock, in buildings dating from 1874 to the 1960s.|The adjacent World War II warehouses of the Ministry of Food Buffer Depot in the former downside yard are used to display many items awaiting restoration, and the Quainton Railway Society have added a members\' reference library.|As one of the best-preserved period railway stations in England, Quainton Road is regularly used as a filming location, and has appeared in <em>The Jewel in the Crown</em>, <em>Black Orchid</em>, and <em>Midsomer Murders</em>.', 'Buckinghamshire Railway Centre was used for the filming of location tasks during series 8 of Taskmaster UK', 'The location was first seen during the \'<a href=\"/task.php?id=327\">Sneak up on Alex</a>\' task, in the first episode of series 8.'),
(10, 'Chesham Town Hall', 'other', NULL, NULL, 'https://www.chesham.gov.uk/Town_Hall/Town_Hall.aspx', NULL, NULL, '010_chesham_town_hall.jpg', '010_chesham_town_hall_thumb.jpg', '010_chesham_town_hall_2.jpg', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d362.59051025521353!2d-0.6138808026146328!3d51.70491214421785!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x48765d0b0df8b9bd%3A0x216fc5100ad29586!2sChesham%20Town%20Hall!5e1!3m2!1sen!2suk!4v1699746948731!5m2!1sen!2suk', 'Chesham Town Hall was opened in 1998, and serves as the home of the Council offices, and also as a hireable venue, with two fully-equipped function rooms (The Council Chamber, and The Community Hall) available for both private and social use.', 'Chesham Town Hall was used as a location for a single task in series 2 of Taskmaster UK.', 'The location was seen only in the \'<a href=\"/task.php?id=50\">Impress the Mayor</a> task, in the third episode of series 2.'),
(11, 'Chesham United Football Club', 'other', NULL, NULL, 'https://www.cheshamunited.co.uk/', 'https://en.wikipedia.org/wiki/Chesham_United_F.C.', 'https://www.instagram.com/cheshamutdfc/', '011_chesham_united_football_club.jpg', '011_chesham_united_football_club_thumb.jpg', '011_chesham_united_football_club_2.jpg', 'https://www.google.com/maps/embed?pb=!1m14!1m12!1m3!1d725.2781918308868!2d-0.6141204210612574!3d51.69884971250307!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!5e1!3m2!1sen!2suk!4v1699747017298!5m2!1sen!2suk', 'Chesham United Football Club is a semi-professional football club in Chesham, Buckinghamshire.|Nicknamed \'The Generals\', the team is currently in the Southern League Premier Division South, and its grounds are known as \'The Meadow\'.', 'Chesham United Football Club\'s grounds were used for the filming of some location-based tasks in series 4.|Also, Alex Horne is a supporter of the team, and currently serves on its board of directors.', 'The location is first seen during the \'<a href=\"/task.php?id=127\">Score a goal with a shopping bag</a>\' task, in episode 6 of series 4.'),
(12, 'Chiltern Open Air Museum', 'other', NULL, NULL, 'https://coam.org.uk/', 'https://en.wikipedia.org/wiki/Chiltern_Open_Air_Museum', 'https://www.instagram.com/chilternoam/', '012_chiltern_open_air_museum.jpg', '012_chiltern_open_air_museum_thumb.jpg', '012_chiltern_open_air_museum_2.jpg', 'https://www.google.com/maps/embed?pb=!1m14!1m12!1m3!1d726.303473272238!2d-0.5429077975730886!3d51.63485240712463!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!5e1!3m2!1sen!2suk!4v1699747146950!5m2!1sen!2suk', 'Chiltern Open Air Museum (COAM) is an independent open-air museum of vernacular buildings and a tourist attraction located near Chalfont St Peter and Chalfont St Giles in the Chiltern Hills, Buckinghamshire.|The museum was founded in 1976 and opened to the public in 1981.|Its collection consists mainly of historic buildings which were at risk of demolition before being dismantled and reconstructed in the museum grounds.|Buildings of interest include: a 1940s prefab from Amersham; a reconstruction of an Iron Age house; a Victorian toll house from High Wycombe; a tin chapel from Henton, Oxfordshire; a forge from Garston, Hertfordshire; a pair of labourer\'s cottages from Leagrave, near Luton; a chair factory from High Wycombe; reconstructed WW1 and WW2 Nissen huts, and a wychert-style farmhouse from Haddenham.|The museum\'s collection also includes 16 buildings that are held in storage and await reconstruction, as and when the museum\'s funds permit.|The museum also offer hands-on activities and traditional skills experiences including blacksmithing, willow sculpting and weaving, straw plaiting, historic cooking, and folk singing, and is a location for many annual historical re-enactments and living history displays.|With its historic buildings, the museum has been used as a filming location for many TV and film productions, and has appeared in <em>Mary Queen of Scots</em>, <em>Downton Abbey</em>, <em>Inside No 9</em>, <em>Call the Midwife</em>, <em>Grantchester</em>, <em>Midsommer Murders</em>, <em>Horrible Histories</em>, <em>The Suspicions of Mr Whicher</em>, <em>Bramwell</em>, and <em>Shine on Harvey Moon</em>.', 'Chiltern Open Air Museum was used for filming many location-based tasks in series 13 of Taskmaster UK.', 'The location was first seen during the \'<a href=\"/task.php?id=1895\">Tie a ribbon round the maypole or hit it with a ping pong ball</a>\' task, in the second episode of series 13.'),
(13, 'Dukes Meadows Golf, Tennis & Ski', 'other', NULL, NULL, 'https://www.dukesmeadows.com/', NULL, 'https://www.instagram.com/dukesmeadows/', '013_duke_meadows_golf_tennis_ski.jpg', '013_duke_meadows_golf_tennis_ski_thumb.jpg', '013_duke_meadows_golf_tennis_ski_2.jpg', 'https://www.google.com/maps/embed?pb=!1m14!1m12!1m3!1d2915.561581588349!2d-0.2640132087142015!3d51.473126402278034!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!5e1!3m2!1sen!2suk!4v1699747239917!5m2!1sen!2suk', 'Dukes Meadows Golf, Tennis & Ski is a sports facility located in Chiswick, West London, featuring a nine-hole golf course, driving range, indoor and outdoor tennis courts, and indoor ski slope.', 'The facility also owns the <a href=\"/location.php?id=1\">Taskmaster house</a>, and has occasionally featured in the show as a task location in its own right since the first series.', 'The location was first seen during <a href=\"/attempt.php?id=125\">Roisin, Romesh and Josh\'s attempt</a> at  the \'<a href=\"/task.php?id=30\">Make a bed while holding hands</a>\' task, in the fifth episode of series 1.'),
(14, 'Eden Shopping Centre', 'other', NULL, NULL, 'https://www.edenshopping.co.uk/', 'https://en.wikipedia.org/wiki/Eden_Shopping_Centre', NULL, '014_eden_shopping_centre.jpg', '014_eden_shopping_centre_thumb.jpg', '014_eden_shopping_centre_2.jpg', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d1452.7549696057063!2d-0.7557562861713949!3d51.6302304734252!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x487661d716e05d6d%3A0xb77f12ec75527d2c!2s7%20Newland%20St%2C%20High%20Wycombe%20HP11%202BY!5e1!3m2!1sen!2suk!4v1699747390698!5m2!1sen!2suk', 'The Eden Shopping Centre, commonly known as Eden, is a shopping and entertainment complex in High Wycombe, Buckinghamshire.|The centre has 107 shops, a bowling alley, a cinema, a library, 48 residential flats, and parking for 1,600 cars on site.|The shopping centre official opened in 2008.|It was used as a filming location for the <em>Black Mirror</em> episode, <em>The Waldo Moment</em>.', 'The shopping centre was used for the filming of two tasks in series 1 of Taskmaster UK, though only one of them made it to air.', 'The location was seen in the \'<a href=\"/task.php?id=8\">High-five a 55-year-old</a>\' task, in the second episode of series 5.'),
(15, 'Frensham Common and Ponds', 'other', NULL, NULL, 'https://www.waverley.gov.uk/Services/Greenspaces-leisure-and-things-to-do/Greenspaces-in-Waverley/Key-Sites/Frensham-Great-Pond', 'https://en.wikipedia.org/wiki/Frensham_Common', NULL, '015_frensham_common_and_ponds.jpg', '015_frensham_common_and_ponds_thumb.jpg', '015_frensham_common_and_ponds_2.jpg', 'https://www.google.com/maps/embed?pb=!1m14!1m12!1m3!1d11742.040589420341!2d-0.7869809433990709!3d51.16031507785842!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!5e1!3m2!1sen!2suk!4v1699747739814!5m2!1sen!2suk', 'Frensham Common is a large Site of Special Scientific Interest heathland covering 373 hectares, which includes two lakes known as Great Pond and Little Pond. It is owned and operated by the National Trust, and managed by Waverley Borough Council.|The area is popular with visitors, particularly in summer months. Swimming is allowed at the Great Pond, within marked areas. A sailing club also operates on the Great Pond. Both ponds have car parking, toilets, cafés, and picnic areas.|The Common and ponds have been used as a filming location for productions including <em>The Hound of the Baskervilles</em> (1959), <em>Carry On Jack</em> (1963), the <em>Doctor Who</em> serial <em>The Highlanders</em> (1966), <em>The Riddle of the Sands</em> (1979), <em>Carry On Columbus</em> (1992), <em>The Mummy</em> (1999), <em>Snow White and The Huntsman</em> (2012), <em>The Witcher</em> (2019), and <em>The Witcher: Blood Origin</em> (2022).', 'The Common and its ponds were used as a filming location for tasks during series 5 of Taskmaster UK.', 'The location was first seen during the \'<a href=\"/task.php?id=148\">Get Alex to dry land</a>\' task, in the first episode of series 5.'),
(16, 'Frogmore Paper Mill', 'other', NULL, NULL, 'https://frogmorepapermill.org.uk/', 'https://en.wikipedia.org/wiki/Frogmore_Paper_Mill', 'https://www.instagram.com/frogmorepapermill/', '016_frogmore_paper_mill.jpg', '016_frogmore_paper_mill_thumb.jpg', '016_frogmore_paper_mill_2.jpg', 'https://www.google.com/maps/embed?pb=!1m14!1m12!1m3!1d724.641233413801!2d-0.46846258465573953!3d51.73857976247609!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!5e1!3m2!1sen!2suk!4v1699747886532!5m2!1sen!2suk', 'Frogmore Paper Mill is a working paper mill situated in Apsley, Hertfordshire. The mill is on an island in the River Gade, which forms part of the Grand Union Canal. It is the oldest mechanical paper mill in the world.|For most of the 19th century, the mill was owned by the Grand Junction Canal (predecessor of the Grand Union Canal). In 1851, the chemical production of paper from wood, used in newspapers, began at the mill.|From 1853 to 1887, the mill was linked to Two Waters Mill, also near Hemel Hempstead.|In 1890, the British Paper Company was founded and took over operations at the mill; it fully purchased the premises in 1929.|In 2000, the British Paper Company ceased operations and the Apsley Paper Trail was opened to the public.|In 2008, a visitor centre was built with financial support from the Heritage Lottery Fund.|The mill is now run by The Apsley Paper Trail, a charitable organisation, and operated as a visitor, education and community use centre.|It has been used for various theatrical productions, including the rock musical <em>Rent</em>.|The visitor centre was badly damaged in a fire in January 2022.', 'The mill was used as a filming location for tasks in series 15 of Taskmaster UK.', 'The location was first seen during the \'<a href=\"/task.php?id=2462\">Get all the rubber rings on your bargepole</a>\' task, in the first episode of series 15.'),
(17, 'Gatwick South Terminal', 'other', NULL, NULL, 'https://www.gatwickairport.com/', 'https://en.wikipedia.org/wiki/Gatwick_Airport#South_Terminal', NULL, '017_gatwick_south_terminal.jpg', '017_gatwick_south_terminal_thumb.jpg', '017_gatwick_south_terminal_2.jpg', 'https://www.google.com/maps/embed?pb=!1m14!1m12!1m3!1d733.9489482335755!2d-0.16325213016938392!3d51.15582593588297!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!5e1!3m2!1sen!2suk!4v1699748029060!5m2!1sen!2suk', 'London Gatwick, also known as Gatwick Airport, is the secondary international airport serving London, located in Horley, Surrey.|In 2022, Gatwick was the second-busiest airport by total passenger traffic in the UK, after Heathrow Airport, and was the 8th-busiest in Europe, by total passenger traffic.|The airport\'s South Terminal, opened in 1958, and subsequently expanded, has 32 gates with jetbridges and 7 remote gates.|The terminal was temporarily closed from June 2020, owing to a sharp decline in passenger traffic as a result of the impact of the Covid-19 pandemic. It fully reopened in March 2022.', 'The terminal was used as a filming location for tasks during the fourteenth series of Taskmaster UK, while it was closed down during the Covid-19 pandemic.', 'The location was first seen in the \'Land loo roll in the toilet\' task, in the first episode of series 14.'),
(18, 'Girlguiding Headquarters Chesham', 'other', NULL, NULL, 'https://girlguidingbucks.org.uk/', NULL, NULL, '018_girl_guiding_headquarters_chesham.jpg', '018_girl_guiding_headquarters_chesham_thumb.jpg', '018_girl_guiding_headquarters_chesham_2.jpg', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d181.29518196281933!2d-0.6169908222127699!3d51.70493040219518!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x48765d0a8de01b59%3A0x25a16c9e0c820148!2sGirl%20Guiding%20Headquarters%20Chesham!5e1!3m2!1sen!2suk!4v1699748158975!5m2!1sen!2suk', 'This building is the Chesham-based headquarters for the Chesham Vale Division of Girlguiding Buckinghamshire County.', 'The headquarters was used as a filming location for tasks in series 6 of Taskmaster UK.', 'The location was first seen in the \'<a href=\"/task.php?id=240\">Make a parachute for a wooden spoon</a>\' task, in episode 6 of series 6.'),
(19, 'JPS Stationers', 'other', NULL, NULL, 'https://jpschesham.com/', NULL, 'https://www.instagram.com/jpsstationers/', '019_jps_stationers.jpg', '019_jps_stationers_thumb.jpg', '019_jps_stationers_2.jpg', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d181.30019825856087!2d-0.6131171425109411!3d51.703678595202824!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x48765d0b45041a9b%3A0x3aa44fcf22a267db!2sJ%20P%20S%20Stationers%20Ltd!5e1!3m2!1sen!2suk!4v1699748262971!5m2!1sen!2suk', 'JP Stationers is a stationery shop located in Chesham, Buckinghamshire.', 'The shop was used as a filming location for a single task in series 6 of Taskmaster UK.', 'The location was seen during the \'<a href=\"/task.php?id=257\">Make an outfit with stationery / Guess what pun Tim will make</a>\' task, in episode 9 of series 6.'),
(20, 'Living Props', 'other', NULL, NULL, 'https://www.livingprops.co.uk/', NULL, 'https://www.instagram.com/livingpropsltd/', '020_living_props.jpg', '020_living_props_thumb.jpg', '020_living_props_2.jpg', 'https://www.google.com/maps/embed?pb=!1m14!1m12!1m3!1d363.8171156587393!2d-0.5222645321313262!3d51.55170298395778!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!5e1!3m2!1sen!2suk!4v1699748426303!5m2!1sen!2suk', 'Living Props has been a provider of greenery and outdoor props to the film, TV and entertainment industry since 1991.|The business has provided services to productions including <em>A Quiet Place Part III</em>, <em>Alice Through the Looking Glass</em>, <em>Alien Covenant</em>, <em>Assassin\'s Creed</em>, <em>Avengers: Age of Ultron</em>, <em>Batman Begins</em>, <em>Black Widow</em>, <em>Bridget Jones\'s Diary</em>, <em>Bridget Jones: Edge of Reason</em>, <em>Casino Royale</em>, <em>Charlie and the Chocolate Factory</em>, <em>Deadpool 3</em>, <em>Die Another Day</em>, <em>Doctor Strange</em>, <em>Dumbo</em>, <em>Eyes Wide Shut</em>, <em>Game of Thrones</em>, <em>Love Actually</em>, <em>Mamma Mia!</em>, <em>Quantum of Solace</em>, <em>Ready Player One</em>, <em>Rosemary & Thyme</em>, <em>Shaun of the Dead</em>, <em>Skyfall</em>, <em>Spectre</em>, <em>Star Wars: The Last Jedi</em>, <em>The Davinci Code</em>, <em>The Fifth Element</em>, <em>The Golden Compass</em>, <em>The Inbetweeners 2</em>, <em>The Mummy</em>, and <em>The Mummy Returns</em>.', 'Living Props was used as a location for the filming of tasks in series 9 of Taskmaster UK.', 'The location was first seen in the \'<a href=\"/task.php?id=382\">Arrange the lollies in rainbow order</a>\' task, in the first episode of series 9.'),
(21, 'London Printworks', 'other', NULL, NULL, 'https://printworkslondon.co.uk/', 'https://en.wikipedia.org/wiki/Printworks_(London)', 'https://www.instagram.com/printworkslondon/', '021_printworks.jpg', '021_printworks_thumb.jpg', '021_printworks_2.jpg', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d364.25065799513544!2d-0.04362782962271256!3d51.49747357098057!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x48760320e17dcf07%3A0x59a1321bada2b317!2sPrintworks%20London!5e1!3m2!1sen!2suk!4v1699748582010!5m2!1sen!2suk', 'Printworks was a nightclub and events venue in Rotherhithe, South London, located in the former Harmsworth Quays printing plant, which had printed newspapers including the <em>Daily Mail</em> and <em>Evening Standard</em> until 2012.|Some features of the printing plant were retained for the club, including the van loading dock and metal stairs, creating an industrial feel. The premises had an overall capacity of 6,000 people across two performance rooms: the Press Halls and Inkwells (formerly known as the Darkroom). The site was also available for hire and was used for events, movies and commercials.|In autumn 2021, the owners of the site, British Land, submitted plans to Southwark Council to redevelop the site into office buildings which would involve the demolition of the Printworks venue. This was widely opposed by the music community as destruction of a key part of London\'s music scene. In 2022, the plans were approved, and Printworks held its final event on 1 May 2023.', 'Printworks was used as a filming location for tasks in series 10 of Taskmaster UK.', 'The location was first seen in the \'<a href=\"/task.php?id=435\">Get the most eggs in the pan</a>\' task, in the first episode of series 10.'),
(22, 'Northala Fields', 'other', NULL, NULL, 'https://www.ealing.gov.uk/info/201136/parks_in_the_borough/663/greenford_parks/2', 'https://en.wikipedia.org/wiki/Northala_Fields', 'https://www.instagram.com/northalafields/', '022_northala_fields.jpg', '022_northala_fields_thumb.jpg', '022_northala_fields_2.jpg', 'https://www.google.com/maps/embed?pb=!1m14!1m12!1m3!1d1455.6336011706812!2d-0.3732661288021799!3d51.54028808307698!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!5e1!3m2!1sen!2suk!4v1699748680420!5m2!1sen!2suk', 'Northala Fields is a park located in Northolt, in the London Borough of Ealing. It was opened in 2008 and consists of four artificial hills standing next to the A40 Western Avenue, as well as several fishing lakes, a large field area, a children\'s play area, and adjacent café.|The hills were constructed using rubble from the demolition of the original Wembley Stadium, which was closed in 2000 and demolished in 2003. The park was created as part of the Northolt and Greenford Country Park project, and backs onto the older Rectory Park.', 'Northala fields was used as the location for the filming of a single task in Taskmaster UK.', 'The location appeared in the \'<a href=\"/task.php?id=39\">Place the exercise balls on the yoga mat</a>\' task, in the first episode of series 2.'),
(23, 'River Misbourne, Amersham', 'other', NULL, NULL, NULL, 'https://en.wikipedia.org/wiki/River_Misbourne', NULL, '023_river_misbourne.jpg', '023_river_misbourne_thumb.jpg', '023_river_misbourne_2.jpg', 'https://www.google.com/maps/embed?pb=!1m13!1m8!1m3!1d362.892120090903!2d-0.614317025737075!3d51.66726961450175!3m2!1i1024!2i768!4f13.1!3m2!1m1!2zNTHCsDQwJzAyLjEiTiAwwrAzNic1MS43Ilc!5e1!3m2!1sen!2suk!4v1699748826841!5m2!1sen!2suk', 'The River Misbourne rises in a field on the outskirts of Great Missenden in Buckinghamshire, passing through Little Missenden, Old Amersham, Chalfont St Giles, Chalfont St Peter and under the Chiltern railway line and the M25 motorway to its confluence with the River Colne.', 'A section of the River Misbourne in Amersham was used as the location for a single task in series 2 of Taskmaster UK.', 'The location appeared in the \'<a href=\"/task.php?id=62\">Move items across a stream</a>\' task in episode 5 of series 2.'),
(24, 'The Black Horse Inn', 'other', NULL, NULL, NULL, NULL, NULL, '024_the_black_horse_inn.jpg', '024_the_black_horse_inn_thumb.jpg', '024_the_black_horse_inn_2.jpg', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d181.18845880093625!2d-0.606190319193008!3d51.731557848390025!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x48765da9665ad6bb%3A0x7b574855d89cf56b!2sHungry%20Olive!5e1!3m2!1sen!2suk!4v1699749148695!5m2!1sen!2suk', 'The pub formerly known as The Black Horse Inn, located in Chesham, reopened as The Hungry Olive in May 2023, but then closed again at the end of that year.|When the pub went up for sale, it was described as including a bar with open fireplaces and exposed beams, a dining and restaurant area catering for up to 40 diners, two kitchens, a beer cellar, and toilets.|The property also featured a self-contained barn with its own bar, toilets, and grill area, for up to 70 guests.|The pub garden had seating for around 180 guests, and there was also a ‘Secret Garden’, hireable for events.', 'The Black Horse was used for the filming of tasks during series 6 of Taskmaster UK.', 'The location was first seen in the \'<a href=\"/task.php?id=213\">Get the highest darts score</a>\' task.'),
(25, 'Quintin Hogg Memorial Sports Ground', 'other', NULL, NULL, 'https://www.westminster.ac.uk/current-students/university-life/sport-and-leisure/chiswick-sports-ground', NULL, NULL, '025_university_of_westminster_sports_ground.jpg', '025_university_of_westminster_sports_ground_thumb.jpg', '025_university_of_westminster_sports_ground_2.jpg', 'https://www.google.com/maps/embed?pb=!1m14!1m12!1m3!1d728.841303071363!2d-0.26694181392415417!3d51.47619887478575!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!5e1!3m2!1sen!2suk!4v1699749635820!5m2!1sen!2suk', 'The Quintin Hogg Memorial Sports Ground at Chiswick is used by students at the University of Westminster.|The sports ground\'s facilities include pitches for football, rugby, hockey, lacrosse, cricket, tennis and netball.|The grounds also include a pavilion with function rooms, bars, catering provision, and changing facilities.', 'The Sports Grounds have occasionally been used for the filming of tasks, since the first series of Taskmaster UK.', 'The location was first seen in the \'<a href=\"/task.php?id=14\">Draw an image using a GPS Device</a>\' task.'),
(26, 'White Waltham Airfield', 'other', NULL, NULL, 'https://www.wlac.co.uk/', 'https://en.wikipedia.org/wiki/White_Waltham_Airfield', NULL, '026_white_waltham_airfield.jpg', '026_white_waltham_airfield_thumb.jpg', '026_white_waltham_airfield_2.jpg', 'https://www.google.com/maps/embed?pb=!1m14!1m12!1m3!1d1456.9319566967797!2d-0.7655123560884044!3d51.49968446383207!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!5e1!3m2!1sen!2suk!4v1699749972612!5m2!1sen!2suk', 'White Waltham Airfield is an operational general aviation aerodrome located at White Waltham, in Berkshire, England.|The large grass airfield is best known for its association with the Air Transport Auxiliary between 1940 and 1945, and for its history of pre-war flying training, wartime and post-war RAF use, and post-war use as a flight test centre by the Fairey and Westland aircraft companies.|In the mid-1950s it was the headquarters of RAF Home Command.|The airfield remained under RAF control until 1982, when it was purchased by the current owners. Until 2007, it was the base of Thames Valley & Chiltern Air Ambulance helicopter.|It is now home to the West London Aero Club, and approximately 150 light aircraft are based at the airfield.', 'White Waltham Airfield was used as a location for filming tasks during series 11 of Taskmaster UK.', 'The location is first seen during the \'<a href=\"/task.php?id=729\">Deliver all the plates to Alex</a>\' task, in the first episode of series 11.'),
(27, 'Woodrow High House', 'other', NULL, NULL, 'https://woodrowhighhouse.org/', NULL, 'https://www.instagram.com/woodrowhighhouse/', '027_woodrow_high_house.jpg', '027_woodrow_high_house_thumb.jpg', '027_woodrow_high_house_2.jpg', 'https://www.google.com/maps/embed?pb=!1m14!1m12!1m3!1d1451.8073159121675!2d-0.6529351014360392!3d51.65981530581745!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!5e1!3m2!1sen!2suk!4v1699750071754!5m2!1sen!2suk', 'Woodrow High House, located in Amersham, Buckinghamshire, is owned by the London Youth organisation.|The house dates from the 17th century, and is said to have housed the Cromwell family during the English civil war.|The house was used as an ammunition depot during World War I, and was used to house evacuated children from Portsmouth during World War II.|London Youth has owned and operated Woodrow High House since 1945, when it was gifted to the organisation (then known as Federation of Boys Clubs) by the Worshipful Goldsmiths Guild. The mission of the charity is to ensure that children and young people have opportunities to grow in confidence, develop leadership skills, build resilience, and create positive relationships with their peers.|The 26-acre facility has evolved into a 120-bed residential centre for visiting schools and youth groups all year round, as well as providing a purpose-built leisure centre with a swimming pool which is hired by local adult community groups and used by Woodrow Swim School.|Facilities include a large campsite area, multi-purpose sports hall, a floodlit astro-turf pitch, and off-road mountain bike circuit.', 'Woodrow High House and its grounds were used as a location for filming tasks during series 7 of Taskmaster UK.', 'The location was first seen during the \'<a href=\"/task.php?id=267\">Build the tallest cardboard box tower</a>\' task, in the first episode of series 7.'),
(28, 'Wormsley Estate', 'other', NULL, NULL, 'https://wormsley.com/', NULL, 'https://www.instagram.com/wormsleyestate/', '028_wormsley_estate.jpg', '028_wormsley_estate_thumb.jpg', '028_wormsley_estate_2.jpg', 'https://www.google.com/maps/embed?pb=!1m14!1m12!1m3!1d1452.3144925825886!2d-0.9319165158922039!3d51.643983243937775!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!5e1!3m2!1sen!2suk!4v1699750389455!5m2!1sen!2suk', 'Founded by the Scrope family in the late 16th Century and passing to descendent Thomas Fane in 1720, the Wormsley Estate remained with the Fane family until it was bought by Sir Paul Getty in 1985.|Sir Paul and Lady Getty embarked on a restoration of the estate, renovating more than 30 buildings including Wormsley House and The Walled Gardens.|The improvement programme also involved additions such as the Deer Park Lake, a world-renowned cricket ground, and the castellated library, which houses one of the finest private collections of books and manuscripts in the country.|Today, Wormsley is one of the residences of Mark and Caterina Getty and their family. Mark’s passion for the arts and opera is most visible through his decision in 2011 to provide a home on the estate for Garsington Opera, and the construction of the Opera Pavilion.|Although primarily a private family home, the estate is used by individuals and organisations to host meetings, conferences, private dining experiences, festivals, corporate days, family days, cricket events, country sports days, private parties, and weddings, accommodating up to 5,000 guests.', 'The Wormsley Estate is used as a location for filming tasks in series 16 of Taskmaster UK.', 'The location is first seen during the \'<a href=\"/task.php?id=2711\">Get the duck into the lake</a>\' task, in the first episode of series 16.'),
(29, 'Kongen Befaler House (Season 1)', 'house', 4, 1, NULL, NULL, NULL, '029_kongen_befaler_house_i.jpg', '029_kongen_befaler_house_i_thumb.jpg', NULL, 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d296.8232115335847!2d10.708900394435252!3d59.921337442389365!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x46416dd1f78894f5%3A0xfed154dd74e3dbe5!2sEckersbergs%20gate%2018%2C%200266%20Oslo%2C%20Norway!5e1!3m2!1sen!2suk!4v1702243887383!5m2!1sen!2suk', 'This is a detached house on Eckersberg Gate in Oslo.', 'The house was used for the production of pre-filmed tasks during the first season of Kongen Befaler.', 'The location is first seen during the \'<a href=\"/task.php?id=737\">Unravel the reel of string</a>\' task, in the first episode of season 1.'),
(30, 'Kongen Befaler House (Seasons 2 - 5)', 'house', 4, 2, NULL, NULL, NULL, '030_kongen_befaler_house_ii.jpg', '030_kongen_befaler_house_ii_thumb.jpg', NULL, 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d296.6917318364477!2d10.69769262262128!3d59.93603572111638!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x46416dc08d9af4df%3A0x2e718c07b2786725!2sBorgenbakken%2024%2C%200370%20Oslo%2C%20Norway!5e1!3m2!1sen!2suk!4v1702244091267!5m2!1sen!2suk', 'This is a detached house on Borgenbakken in Oslo.', 'The house was used for the production of pre-filmed tasks during seasons 2 through 5 of Kongen Befaler.', 'The location is first seen during the \'<a href=\"/task.php?id=1565\">Throw something into the bucket behind the hedge</a>\' task, in the first episode of season 2.'),
(31, 'Kongen Befaler House (Seasons 6 - )', 'house', 4, 3, NULL, NULL, NULL, '031_kongen_befaler_house_iii.jpg', '031_kongen_befaler_house_iii_thumb.jpg', NULL, 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d296.8910001633393!2d10.631383293909701!3d59.913758413982585!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x46416cfb3c5ef51d%3A0xf5251e82104a4b2f!2sPbs%20-%20Pol%20bygg%20service!5e1!3m2!1sen!2suk!4v1702244288584!5m2!1sen!2suk', 'This is a detached house on Solliveien, in Viken county, near Oslo.', 'The house has been used for the production of pre-filmed tasks since the sixth season of Kongen Befaler.', 'The location is first seen during the \'<a href=\"/task.php?id=2129\">Eat the melba toast</a>\' task, in the first episode of season 6.'),
(32, 'Stormester House (Season 1)', 'house', 6, 1, NULL, NULL, NULL, '032_stormester_house_i.jpg', '032_stormester_house_i_thumb.jpg', '032_stormester_house_i_2.jpg', 'https://www.google.com/maps/embed?pb=!1m14!1m8!1m3!1d147.8144821127807!2d12.588994166246634!3d55.75550979437498!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x46524d0321462ff3%3A0x9f05be95116d6589!2sStormester%20huset%20s%C3%A6son%201!5e1!3m2!1sen!2suk!4v1743805994595!5m2!1sen!2suk', 'This is a detached house on Strandhøjsvej in Charlottenlund, near Copenhagen, Denmark.', 'The house was used for the production of pre-filmed tasks during the first season of Stormester.', 'The house was first seen during the \'<a href=\"/task.php?id=565\">Throw a teabag into a mug</a>\' task, during the first episode of season 1.'),
(33, 'Stormester House (Season 2)', 'house', 6, 2, NULL, NULL, NULL, '033_stormester_house_ii.jpg', '033_stormester_house_ii_thumb.jpg', '033_stormester_house_ii_2.jpg', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d331.27750019727716!2d12.55623804580687!3d55.98811425557976!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x46523718a341cd2f%3A0x9a2b0e74154943e7!2sAndersen%20Reklame%20%26%20Illustration!5e1!3m2!1sen!2suk!4v1702398605509!5m2!1sen!2suk', 'This is a detached house on Strandvejen in Espergærde, Denmark.', 'The house was used for the production of pre-filmed tasks during the first season of Stormester.', NULL),
(34, 'Stormester House (Season 3)', 'house', 6, 3, NULL, NULL, NULL, '034_stormester_house_iii.jpg', '034_stormester_house_iii_thumb.jpg', '034_stormester_house_iii_2.jpg', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d166.82519745675123!2d12.567631034691786!3d55.75349751648687!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x46524d9104907c8d%3A0x5a1d627a113760b!2sHeilsmindevej%202%2C%202920%20Charlottenlund%2C%20Denmark!5e1!3m2!1sen!2suk!4v1702412685078!5m2!1sen!2suk', 'This is a detached house on Heilsmindevej in Charlottenlund, near Copenhagen, Denmark.', 'The house was used for the production of pre-filmed tasks during the second season of Stormester.', NULL),
(35, 'Stormester House (Seasons 4 - 6)', 'house', 6, 4, NULL, NULL, NULL, '035_stormester_house_iv.jpg', '035_stormester_house_iv_thumb.jpg', '035_stormester_house_iv_2.jpg', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d166.82564440821972!2d12.555274774568934!3d55.75339301258375!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x46524ded32f569cb%3A0x86261bebe7540f3b!2sBernstorffsv%C3%A6nget%2011%2C%202820%20Gentofte%2C%20Denmark!5e1!3m2!1sen!2suk!4v1702413239867!5m2!1sen!2suk', 'This is a detached house on Bernstorffsvænget in Gentofte, near Copenhagen, Denmark.', 'The house was used for the production of pre-filmed tasks during seasns 4, 5, and 6 of Stormester.', NULL),
(36, 'Stormester House (Season 7 - One More Chance Special)', 'house', 6, 5, NULL, NULL, NULL, '036_stormester_house_v.jpg', '036_stormester_house_v_thumb.jpg', '036_stormester_house_v_2.jpg', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d166.73500549045872!2d12.369296494205665!3d55.77458308609952!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x46524546e990e7a3%3A0x9145561e8f26a8c8!2sBallerupvej%2062%2C%203500%20V%C3%A6rl%C3%B8se%2C%20Denmark!5e1!3m2!1sen!2suk!4v1702413646085!5m2!1sen!2suk', 'This is a detached house on Ballerupvej in Værløse, near Copenhagen, Denmark.', 'The house was used for the production of pre-filmed tasks for the seventh season of Stormester, plus the Champion of Champions, One More Chance, and Christmas 2023 specials.', NULL),
(37, 'Bäst i Test House (Seasons 1 - 4, and Sämst i Test)', 'house', 3, 1, NULL, 'https://sv.wikipedia.org/wiki/Villa_Frescati', NULL, '037_bäst_i_test_house_i.jpg', '037_bäst_i_test_house_i_thumb.jpg', '037_bäst_i_test_house_i_2.jpg', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d298.1322397864392!2d18.049986374853432!3d59.366496706405734!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x465f9d3f04a6b059%3A0xfefef6d6fd795143!2sVilla%20Frescati!5e1!3m2!1sen!2suk!4v1702418316637!5m2!1sen!2suk', 'Villa Frescati is a building located in Frescati, Stockholm, within the National City Park.|The villa was built in the years 1791-1792, as Gustaf Mauritz Armfelt\'s (a Swedish baron and courtier) summer pleasure on the eastern side of Brunnsviken.|In 1791, Gustav III (King of Sweden from 1771 to 1792) donated an area of ​​land on the eastern side of Brunnsviken to Armfelt. The area that was called Ulriksdal\'s storäng was named Frescati, inspired by Gustav III\'s trip to Italy, in which Armfelt had also taken part.|Originally, it was intended to build a bathhouse at Brunnsvikens beach, and several drafts were made. Although these ideas remained on paper, they influenced the final design of the building.|Armfelt never actually lived in the villa at Frescati as, when its construction was completed, Gustav III had been murdered, and Armfelt had fled the country.', 'The house was used for the production of pre-filmed tasks throughout seasons 1 through 4 of the show.|It was then used for the filming of tasks during the single episode \'Loser of Losers\' special.', NULL),
(38, 'Bäst i Test House (Season 5)', 'house', 3, 2, NULL, 'https://sv.wikipedia.org/wiki/Judiska_teatern', NULL, '038_bäst_i_test_house_ii.jpg', '038_bäst_i_test_house_ii_thumb.jpg', '038_bäst_i_test_house_ii_2.jpg', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d298.451508475624!2d18.132984183128208!3d59.330154512890445!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x465f82bcbc196355%3A0x4249e6e59ea9a209!2sAB%20Judiska%20Teatern%20i%20Sverige!5e1!3m2!1sen!2suk!4v1702418364510!5m2!1sen!2suk', 'The Judiska teatern (Jewish Theatre) was a privately owned Swedish theatre and experimental cultural centre with a focus on Jewish culture, located in Stockholm.|Between 1995 and 2013, it operated from an internally modernised bowling alley built in the 1880s at Djurgårdsbrunnsvägen 59 on Djurgården.|The theatre closed in 2013, but the building itself continues to be used for other purposes.', 'The house was used for the production of pre-filmed tasks throughout season 5 of the show.', NULL),
(39, 'Bäst i Test House (Seasons 6 - 7)', 'house', 3, 3, NULL, NULL, NULL, '039_bäst_i_test_house_iii.jpg', '039_bäst_i_test_house_iii_thumb.jpg', NULL, 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d298.48430538509365!2d17.89583719539573!3d59.32642048319507!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x465f75c031d56659%3A0x42692829a67bbb5f!2s%C3%84ngsholmsv%C3%A4gen%207%2C%20178%2093%20Drottningholm%2C%20Sweden!5e1!3m2!1sen!2suk!4v1702418441793!5m2!1sen!2suk', 'This property is a privately-owned house located on the island of Kärsön in Drottningholm, near Stockholm, Sweden.', 'The house was used for the production of pre-filmed tasks throughout seasons 6 and 7 of the show.', 'The property was first seen in the \'<a href=\"/task.php?id=1569\">Splash Julmust as far as possible</a>\' task, in the first episode of season 6.'),
(40, 'Taskmaster NZ/AU House', 'house', 8, 1, 'https://www.hus.nz/', NULL, 'https://www.instagram.com/husvenue/', '040_taskmaster_nz_au_house.jpg', '040_taskmaster_nz_au_house_thumb.jpg', '040_taskmaster_nz_au_house_2.jpg', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d233.956293186966!2d174.6133138938302!3d-36.72648997913429!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x6d0d3df2e5aa418d%3A0xe516d93f76a55e0!2sHUs%20-%20Boutique%20Venue%20%26%20Accommodation!5e1!3m2!1sen!2suk!4v1703544878007!5m2!1sen!2suk', 'HUs is a 500 square metre, two-storey event and function venue set in 20 acres of land, and located 35 minutes outside of Auckland, in New Zealand.|The venue is used for weddings, corporate conferences and events, wellness retreats, and as a vacation destination, and includes a large space with seating for up to 85 guests, a bar, a kitchen, and accommodation for up to eight guests.|The property also includes a large lawn, wooded areas, and a large pond with a dock.', 'The property is used for the filming of tasks for both Taskmaster NZ, and Taskmaster AU.', 'The interior of the house is first seen in the \'<a href=\"/task.php?id=488\">Make a sculpture of something using items which begin with the same letter</a>\' task, in the first episode of season 1 of Taskmaster NZ.|The exterior of the property is first seen in the \'<a href=\"/task.php?id=490\">Hit a piece of fruit with some bread</a>\' task, also in the first episode of season 1 of Taskmaster NZ.'),
(41, 'Suurmestari House (Seasons 1 - 2)', 'house', 9, 1, 'https://jhlhelsinki.fi/kulosaaren-kartano/', 'https://fi.wikipedia.org/wiki/Kulosaaren_kartano', NULL, '041_suurmestari_house_i.jpg', '041_suurmestari_house_i_thumb.jpg', '041_suurmestari_house_i_2.jpg', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d144.77375408011144!2d25.014375950317035!3d60.193059868805335!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x469209410334a1e1%3A0xbf6c66ddd183901f!2sKulosaari%20Manor!5e1!3m2!1sen!2suk!4v1703697030659!5m2!1sen!2suk', 'Kulosaari Manor is located on the shore of the Naurissalmi strait, opposite Kulosaari island, in Helsinki, Finland.|The history of the estate goes back to the middle of the 16th century, and the current main building was designed by Pehr Granstedt around 1811-1815.|The tobacco drying barn or tobacco barn from the 1750s is the oldest surviving building in the manor area. Today, it is part of the Herttoniemi plantation garden area and is used as a meeting and party space.|Recently, the mansion has been leased to the Helsinki joint organisation of the Association of Public and Welfare Sectors, but this organisation\'s activities ended in September 2023.', 'The mansion and its grounds were used for the production of filmed tasks during the first two seasons of Suurmestari.', NULL),
(42, 'Suurmestari House (Season 3)', 'house', 9, 2, NULL, 'https://fi.wikipedia.org/wiki/Stansvikin_kartano', NULL, '042_suurmestari_house_ii.jpg', '042_suurmestari_house_ii_thumb.jpg', '042_suurmestari_house_ii_2.jpg', 'https://www.google.com/maps/embed?pb=!1m14!1m8!1m3!1d290.45325599937485!2d25.03018553984643!3d60.16363001018935!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x46920c013debe217%3A0xdd4da20079155e8e!2sStansvik%20Manor!5e1!3m2!1sen!2suk!4v1703700880428!5m2!1sen!2suk', 'Stansvik Manor is located in the Laajasalo district of Helsinki in Finland. It has been owned by the city of Helsinki since 1938.|The main building of the mansion is currently used as a museum, and was built in 1803–1804, when it was owned by Captain Fabian Casimir Roswall.|Stansvik Manor began to function as an independent estate in 1798, before which it was a farm belonging to the estate of Degerö Manor.|After Captain Roswall, the manor was owned by the painter Emanuel Thelning between 1805 and 1817. After that, it was first owned by Edelheim and from 1856 by the Willebrand family.|The city of Helsinki bought the 100-hectare manor from the Willebrand family in 1938.|Since 1945, the manor\'s tenant has been the city\'s civil service association (now Jyty Metropoli ry).|In the 1950s, summer apartments were built on the former lands of the manor.', 'The mansion and its grounds were used for the production of filmed tasks during the third season of Suurmestari.', NULL),
(43, 'Suurmestari House (Season 4)', 'house', 9, 3, NULL, 'https://fi.wikipedia.org/wiki/Jollaksen_kartano', 'https://www.instagram.com/jollaksen_kartano/', '043_suurmestari_house_iii.jpg', '043_suurmestari_house_iii_thumb.jpg', '043_suurmestari_house_iii_2.jpg', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d290.44957739971284!2d25.08361457509324!3d60.16404620656364!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x46920bb65d6cffdf%3A0x9279dfefc9ae9d8a!2sKuuma!5e1!3m2!1sen!2suk!4v1703699028077!5m2!1sen!2suk', 'Jollaksen Manor is located in Jollas in Laajasalo, Helsinki.|The manor\'s history dates back to 1798, when its lands were separated from Holmgård Manor. The current main building of the manor - which has protected status - dates from 1919. It was built by deputy judge, banker Viktor Alexander Tavaststjerna, and designed by architects Malmström and Tikkanen.|Over the years, the manor was owned by vicar Pettersson at the end of the 19th century, and after that by station master Robert Rosvall, deputy judge A Laurell, and the Tavaststjerna family.|In 1920, the lands of the manor were divided between Tavaststjerna and his siblings, with the middle part of the estate and the main building going to Viktor Tavaststjerna, the eastern part going to his brother Alarik, and the western part to his sister Selma Alftan.|In 1940, the manor was sold to the S Group (a cooperative retail organisation), which used it as its training facilities. In 1981, when S Group wanted to give up the manor, the city of Helsinki used its right of first refusal to acquire the manor for itself.|In the 2010s, the city tried to sell the mansion, but ended up instead renting it to the restaurant entrepreneur Antti Tuomola. After this, the family cafe business Kuuma Helsinki Oy operated from the manor.|Today, the manor is a meeting and party space, beach sauna venue, and event centre.', 'The mansion and its grounds were used for the production of filmed tasks during the fourth season of Suurmestari.', NULL),
(44, 'South Pacific Pictures', 'studio', NULL, NULL, 'https://southpacificpictures.com/', 'https://en.wikipedia.org/wiki/South_Pacific_Pictures', 'https://www.instagram.com/southpacificpix', '044_south_pacific_pictures.jpg', '044_south_pacific_pictures_thumb.jpg', '044_south_pacific_pictures_2.jpg', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d467.1225130189761!2d174.63861434657926!3d-36.855961283027696!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x6d0d405d15b46f89%3A0x97bd0bce4cf49db7!2sSouth%20Pacific%20Pictures!5e1!3m2!1sen!2suk!4v1703961516080!5m2!1sen!2suk', 'South Pacific Pictures is a New Zealand television production company which creates drama series, mini-series, television movies, and feature films for the domestic and international markets.|SPP\'s largest property is <em>Shortland Street</em>, the half-hour soap opera aired on TVNZ 2.|In 1998, the company produced the feature film <em>What Becomes of the Broken Hearted?</em>, the sequel to <em>Once Were Warriors</em>.|In 2000, the company moved from Browns Bay (Auckland) to a new purpose-built studio complex in Henderson, West Auckland.|In 2002, it produced the Oscar-nominated feature film <em>Whale Rider</em> and, in 2006, it released <em>Sione\'s Wedding</em>.', 'South Pacific Pictures\'s West Auckland studio has been used for the filming of the live studio sessions of some seasons [to be clarified] of Taskmaster NZ.', NULL),
(45, 'NEP Studios', 'studio', NULL, NULL, 'https://www.nepgroup.com.au/services/television-studios-for-hire', NULL, NULL, NULL, NULL, NULL, 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d484.5793947835357!2d151.19369320290605!3d-33.89630523367184!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x6b12b1ce16dd1cc7%3A0xd9e1fba291d025c3!2sNEP%20Australia%20Headquarters%20%26%20Sydney%20Studios!5e1!3m2!1sen!2suk!4v1703965215812!5m2!1sen!2suk', 'The NEP Group owns and runs television production studios in Sydney, Willoughby, and Melbourne, Australia.', 'One of the Sydney studios run by NEP Group was used for the filming of the studio sessions for the first season of Taskmaster AU, and this location is also used for the third season.', NULL),
(46, 'Docklands Studios Melbourne', 'studio', NULL, NULL, 'https://www.dsmelbourne.com/', 'https://en.wikipedia.org/wiki/Docklands_Studios_Melbourne', 'https://www.instagram.com/docklands_studios/', '046_docklands_studios_melbourne.jpg', '046_docklands_studios_melbourne_thumb.jpg', '046_docklands_studios_melbourne_2.jpg', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d922.4104632238648!2d144.93569484435633!3d-37.81354863267222!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x6ad65d6632e85bb9%3A0xa68e734f65b72b92!2s476%20Docklands%20Dr%2C%20Docklands%20VIC%203008%2C%20Australia!5e1!3m2!1sen!2suk!4v1703970463486!5m2!1sen!2suk', 'Docklands Studios Melbourne is a major film and television production complex located in Melbourne’s redeveloped Docklands precinct, approximately 2km from Melbourne’s Central Business District.|The complex opened in 2004, and its primary functions are to support Victoria\'s film and television industry and attract international and Australian productions to Melbourne.|The studio complex consists of six sound stages with a total area of close to 10,000m2 (110,000 sq ft), various production offices, a workshop divided into bays of different sizes, and parking for more than 650 vehicles.|The sound stages vary in size from 743m<sup>2</sup> to 2,323m<sup>2</sup> to (8,000 to 25,000 sq ft), and are used for the production of feature films, drama series, audience-based television programmes, television commercials, music videos, and corporate events. Stage 6 was completed in 2022 and is one of the largest sound stages in the Southern Hemisphere.', 'One of the sound stages at Docklands Studios Melbourne was used for the filming of the studio segments of season 2 of Taskmaster AU.', NULL),
(47, 'Bäst i Test House (Season 8- )', 'house', 3, 4, NULL, 'https://sv.wikipedia.org/wiki/Vilohemmet,_Farsta', NULL, '047_bäst_i_test_house_iv_1.jpg', '047_bäst_i_test_house_iv_thumb_1.jpg', '047_bäst_i_test_house_iv_2.jpg', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d149.3219165221121!2d18.090130135201143!3d59.23256732494407!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x465f79861f527577%3A0xc23a872fb43931b6!2sFarsta%20Ungdomsboende!5e1!3m2!1sen!2suk!4v1704204371737!5m2!1sen!2suk', 'Vilohemmet (\'The Rest Home\'), also known as Ingenjörens hus (\'The Engineer\'s House\'), is an Art Nouveau villa next to Lake Magelungen at Gräsmarkgränd 2 in Farsta strand, southern Stockholm.|The house was built in 1903, in what was then called Södertörn\'s villa town, and is far visible over the nearby Ågesta Bridge.|It is a large, two-storey villa, in light-coloured plaster, and designed in Art Nouveau style, but also reminiscent of 18th-century manor architecture with rusticated façade treatment on the ground floor. The strong floor-separating moulding and the roof cornice bear influences from the 1890s stone city architecture. The steep mansard roof, the dome-shaped, cornice-turned stairwell roof, and the small slatted upper part of the windows were common in the Art Nouveau-inspired style that prevailed when the house was built. Many ceiling and wall paintings from the original period have been preserved, as have the tiled stoves. The original gazebo still remains on the plot.|The house was built as one of the early villas in Södertörn\'s villa town for the engineer and match industry inventor Frans Daniel Lundgren, hence the name \'The Engineer\'s House\'. He lived alone and built an indoor velodrome to be used for exercise, like an exercise bike of the time. After two years, he moved to Östermalm. After that, engineer Hjalmar Fogelmark lived with his wife in the house.|The house was taken over after a few years by the spouses Albert and Hulda Pålson, who in 1928 donated the property to the Stockholm City Hospital Administration to be used as a convalescent home under the name Pålson\'s convalescent home. The house became a sick, nursing, convalescent and youth home in various forms and was then named the Rest Home. The neighbourhood designation is also Vilohemmet.|After 1960, it was run under the auspices of the Fanny Hirsch Minne Foundation, and later by the Vallmotorpet Foundation, as a home for homeless youth. In 1966-1969, the building was rebuilt to accommodate 30 care places and four staff residences.|In 2004, Micasa Fastigheter in Stockholm acquired the property, and began leasing it to a company that runs activities for young people who come to Sweden alone, seeking asylum. While waiting to be assigned a municipality, which is responsible for the young people\'s accommodation and care during the asylum process, they have temporary accommodation in the house.', 'The property has been used for the production of filmed tasks since season 8 of Bäst i Test.', 'The house first appeared in the \'Improvise lyrics about yourself to the Taskmaster theme tune\' task, in the first episode of season 8.'),
(48, 'Dicho y Hecho House', 'house', 5, 1, NULL, NULL, NULL, '048_dicho_y_hecho_house.jpg', '048_dicho_y_hecho_house_thumb.jpg', NULL, NULL, 'The location of this property is not yet know. If you have any information about it, please let us know!', 'The property is used for the production of filmed tasks in the Spanish version of Taskmaster, Dicho y Hecho.', NULL),
(49, 'Taskmaster US House', 'house', 7, 1, NULL, NULL, NULL, '049_taskmaster_us_house.jpg', '049_taskmaster_us_house_thumb.jpg', NULL, 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d241.53149956388273!2d-118.5410478929708!3d34.162245130271046!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x80c299038a8b19e3%3A0x19e875ce966aa2ba!2s5035%20Veloz%20Ave%2C%20Tarzana%2C%20CA%2091356%2C%20USA!5e1!3m2!1sen!2suk!4v1704664347768!5m2!1sen!2suk', 'A private property in the Tarzana neighbourhood of the San Fernando Valley region of Los Angeles, California.', 'The property was used for the production of filmed tasks in the US version of Taskmaster.', NULL),
(50, 'Direktor Svemira House', 'house', 12, 1, NULL, NULL, NULL, '050_direktor_svemira_house.jpg', '050_direktor_svemira_house_thumb.jpg', '050_direktor_svemira_house_2.jpg', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d182.87084236596263!2d16.038726233836506!3d45.8783595340166!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x4765d85a2f2b36db%3A0x505859c1731d2fe9!2sCesari%20ul.%2025%2C%2010000%2C%20Zagreb%2C%20Croatia!5e1!3m2!1sen!2suk!4v1742753376783!5m2!1sen!2suk', 'A private property in Zagreb, Croatia.', 'The property was used for the production of filmed tasks in the Croatian version of Taskmaster, Direktor Svemira.', NULL),
(51, 'Le Maître du Jeu House (Main seasons)', 'house', 13, 1, 'https://skisaintbruno.ca/', 'https://en.wikipedia.org/wiki/Ski_Mont_Saint-Bruno', 'https://www.instagram.com/ski.saint.bruno', '051_le_maître_du_jeu_house.jpg', '051_le_maître_du_jeu_house_thumb.jpg', NULL, 'https://www.google.com/maps/embed?pb=!1m14!1m8!1m3!1d408.7622350035877!2d-73.33460773573604!3d45.55862280785744!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x4cc9019ceb966251%3A0xd7bdf4df82c6830!2sSki%20Saint-Bruno!5e1!3m2!1sen!2suk!4v1704664248196!5m2!1sen!2suk', 'A ski lodge on the slopes of Mont Saint-Bruno, in Saint-Bruno-de-Montarville, an off-island suburb of Montreal, in southwestern Quebec, Canada.', 'The property is used for the production of filmed tasks in the Quebecois version of Taskmaster, Le Maître du Jeu.', NULL),
(52, 'Het Grootste Licht House', 'house', 2, 1, NULL, NULL, NULL, '052_het_grootste_licht_house.jpg', '052_het_grootste_licht_house_thumb.jpg', '052_het_grootste_licht_house_2.jpg', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d183.21102689992827!2d4.436693881556964!3d51.122781818985764!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x47c3f06e60c308eb%3A0x1f4d63f746dd810d!2sKeizershoek%20185%2C%202550%20Kontich%2C%20Belgium!5e1!3m2!1sen!2suk!4v1704663619585!5m2!1sen!2suk', 'A private property in Kontich, Belgium.', 'The property was used for the production of filmed tasks in the Flemish version of Taskmaster, Het Grootste Licht.', NULL),
(53, 'Taskmaster PT House', 'house', 11, 1, NULL, NULL, NULL, NULL, NULL, NULL, 'https://www.google.com/maps/embed?pb=!1m14!1m12!1m3!1d456.13359687725284!2d-9.133083646140197!3d38.618156975637746!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!5e1!3m2!1sen!2suk!4v1704663519800!5m2!1sen!2suk', 'A mansion to the south of Lisbon, Portugal.', 'The property is used for the production of filmed tasks in the Portuguese version of Taskmaster.', NULL),
(54, 'Suurmestari House (Season 5 - )', 'house', 9, 4, 'https://www.kauniainen.fi/kulttuuri-ja-vapaa-aika/juhla-ja-kokoustilat/villa-frosterus/', 'https://fi.wikipedia.org/wiki/Villa_Frosterus', NULL, '054_suurmestari_house_iv.jpg', '054_suurmestari_house_iv_thumb.jpg', '054_suurmestari_house_iv_2.jpg', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d145.4307537592884!2d24.67441652002963!3d60.11742969217535!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x468d8ba4568ee401%3A0x42a02a717894bd12!2sVilla%20Frosterus!5e1!3m2!1sen!2suk!4v1710704957106!5m2!1sen!2suk', 'Villa Frosterus is a two-storey villa located in Soukanniemi, Espoo, Finland.|The villa, completed in 1913, was designed and built by the architect Sigurd Frosterus as his summer retreat.|Sigurd Frosterus also designed the Stockmann department store in 1916, and the villa Tamminiemi in 1904, which formerly served as the Finnish President\'s official residence in Helsinki, but is now home to the Urho Kekkonen Museum.|The town of Kauniainen acquired Villa Frosterus and the six-hectare area of ​​Soukanniemi that surrounds it in 1989, and the area is currently a recreation area for Kauniainen residents, offering opportunities for outdoor activities, beach life, and island experiences.\r\n\r\n', 'The villa is used for the production of pre-filmed tasks in the fifth season of Suurmestari.', NULL),
(55, 'Drammen\'s Theatre', 'studio', NULL, 1, 'https://www.drammenscener.no/teatret/', 'https://no.wikipedia.org/wiki/Drammens_Teater', 'https://www.instagram.com/drammensteater/', '055_drammens_theatre.jpg', '055_drammens_theatre_thumb.jpg', '055_drammens_theatre_2.jpg', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d294.1494618953497!2d10.200247762650932!3d59.74455805260846!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x4641234abf01ab87%3A0xdb2ca094dbc15ac0!2sDrammen%20Theater!5e1!3m2!1sen!2suk!4v1710767792126!5m2!1sen!2suk', 'Drammen\'s Theatre is a theatre located at Øvre Storgate 12 in Drammen, Norway.|Designed on the same model as the Parisian theatres Théâtre de la Porte-Saint-Martin and Théâtre du Châtelet, Drammen\'s theatre has a complex Neo-Renaissance style, with symmetrical facades and round-arched windows.|The original theatre was designed by the architect Emil Victor Langlet, and opened in 1870.|In December 1993, the original theatre was almost completely destroyed by fire, leaving only the outer walls behind. The architect for its reconstruction was Jan Øyvind Berntzen.|The rebuilt theatre was completed in February 1997, with upgraded, modern functionality.', 'The theatre has been used for the production of the live studio segments of Kongen Befaler since 2019.', 'The theatre is first seen at the start of the very first episode of the show.'),
(56, 'The Court Theatre', 'studio', NULL, 1, 'https://www.hofteatret.dk/', 'https://da.wikipedia.org/wiki/Teatermuseet_i_Hofteatret', 'https://www.instagram.com/teatermuseet/', '056_hofteatret.jpg', '056_hofteatret_thumb.jpg', '056_hofteatret_2.jpg', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d656.9254343358255!2d12.578573142997246!3d55.67499393990143!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x4652531422292c35%3A0x2bdecfe7ce185559!2sThe%20Theatre%20Museum%20at%20The%20Court%20Theatre!5e1!3m2!1sen!2suk!4v1710965442899!5m2!1sen!2suk', 'The Court Theatre (\'Hofteatret\') is located at Christiansborg Riding ground in Copenhagen, Denmark, right behind the Danish Parliament.|It opened in 1767 as the King\'s theatre, having been converted from an armoury to a neoclassical theatre space with pillar-supported balconies.|In the early 1840s, King Christian VIII arranged for the theatre to be renovated, transforming it to a Biedermeier interior of red velvet and lodges.|A large theatre fire in Vienna in 1881 resulted in the closure of all wooden theatres in Europe, including the Court Theatre. The following year, all furnishings were sold and the theatre became a space for furniture storage, until the Theatre Museum took up residence there in 1922.|The theatre and museum have both been closed and under renovation since 2021.', 'The theatre was used for the filming of the studio segments of the first four seasons of Stormester.', NULL),
(57, 'The Glass Hall', 'studio', NULL, 2, 'https://www.tivoli.dk/da/haven-og-forlystelser/spillesteder/glassalen', 'https://en.wikipedia.org/wiki/Glass_Hall_(Tivoli_Gardens)', NULL, '057_glassalen.jpg', '057_glassalen_thumb.jpg', '057_glassalen_2.jpg', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d328.4726736754313!2d12.56820338977321!3d55.67380807284818!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x4652530da5016319%3A0x715adbe4a27c85dc!2sGlass%20Hall!5e1!3m2!1sen!2suk!4v1710966661795!5m2!1sen!2suk', 'The Glass Hall (\'Glassalen\') is a 957-seat theatre venue located inside the Tivoli Gardens amusement park and pleasure garden in Copenhagen, Denmark.|The octagonal glass theatre, designed by Poul Henningsen, was built in 1946, after the previous theatre (\'Teatersalen\') was destroyed during the Second World War.', 'The theatre has been used for the filming of the studio segments of Stormester since season 5 (though it was not used for the filming of the \'Vindernes Vinder\' or \'En Chance Til\' specials, as it was not available at the time).', NULL),
(58, 'The Circus Revue Tent', 'studio', NULL, 3, 'https://cirkusrevyen.dk/', 'https://en.wikipedia.org/wiki/Cirkusrevyen', NULL, '058_cirkusrevyen.jpg', '058_cirkusrevyen_thumb.jpg', '058_cirkusrevyen_2.jpg', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d327.6129425116126!2d12.576841170024055!3d55.77614448694273!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x46524db14789ed71%3A0x562b100ce81acda5!2sCirkusrevyen!5e1!3m2!1sen!2suk!4v1710967388280!5m2!1sen!2suk', 'The Circus Revue (\'Cirkusrevyen\') tent is a large performance space in the Bakken amusement park, north of Copenhagen, Denmark.|The Circus Revue was founded at Bakken in 1935 by the restaurateur Carl Pehrsson, the actors Osvald Helmuth and Oscar Holst, and the musician Herman Gellin.', 'The tent was used for the production of the studio segments of Stormester\'s \'Vindernes Vinder\' or \'En Chance Til\' specials.', NULL),
(59, 'SpareBank 1 building', 'other', NULL, NULL, NULL, NULL, NULL, '059_sparebank_1_building.jpg', '059_sparebank_1_building_thumb.jpg', '059_sparebank_1_building_2.jpg', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d291.99542413350684!2d10.751825809312043!3d59.915179418427805!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x46416f090c540efd%3A0x238fa8f1675d1b24!2sSpareBank%201%20Utvikling!5e1!3m2!1sen!2suk!4v1711721981503!5m2!1sen!2suk', 'The SpareBank 1 building is a commercial property located on Hammersborggata in Oslo, Norway.|It appears that one of the occupants of the top floor of the building is the production company Nordisk Banijay, which produces Kongen Befaler.', 'The building is used as the starting location for a task in season 9 of Kongen Befaler.', 'The building is first seen in the \'Carry the flag pole out of the building\' task, in the fourth episode of season 9 of Kongen Befaler.'),
(60, 'Arbeidersamfunnets plass', 'other', NULL, NULL, NULL, NULL, NULL, '060_arbeidersamfunnets_plass.jpg', '060_arbeidersamfunnets_plass_thumb.jpg', '060_arbeidersamfunnets_plass_2.jpg', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d291.9920736202858!2d10.751184266637063!3d59.915560291241526!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x46416e63daa48c09%3A0x8f7ff99ce9f22a7c!2sWorkers&#39;%20Place%2C%200181%20Oslo%2C%20Norway!5e1!3m2!1sen!2suk!4v1711722583672!5m2!1sen!2suk', 'Arbeidersamfunnets plass (\'Worker society’s place\') is a square in the Hausmann area of central Oslo, Norway.|The square takes its name from an eight-storey building, completed in 1941 in a functionalist style, where the Sentrum cinema was formerly located (now the location of Sentrum Scene).|The square is located in the area where a penitentiary was previously located, between c1740 and the 1930s. Some of the stone walls from the penitentiary have been preserved in the adjacent police building, and in a restaurant in a neighbouring building.', 'The square is used as the ending location for a task in season 9 of Kongen Befaler.', 'The square is first seen in the \'Carry the flag pole out of the building\' task, in the fourth episode of season 9 of Kongen Befaler.'),
(61, 'St Hanshaugen Park', 'other', NULL, NULL, 'https://www.oslo.kommune.no/natur-kultur-og-fritid/tur-og-friluftsliv/parker-og-friomrader/st-hanshaugen/#gref', 'https://en.wikipedia.org/wiki/St._Hanshaugen#Park', NULL, '061_st_hanshaugen_park.jpg', '061_st_hanshaugen_park_thumb.jpg', '061_st_hanshaugen_park_2.jpg', 'https://www.google.com/maps/embed?pb=!1m14!1m8!1m3!1d291.88665416792264!2d10.7408259!3d59.9275432!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x46416f9492433795%3A0xb8422f1b895b54f7!2sSt.%20Hanshaugen%20park!5e1!3m2!1sen!2suk!4v1711722948229!5m2!1sen!2suk', 'St Hanshaugen Park is one of Oslo\'s largest parks, situated just north of the city centre. The popular recreational area is great for walks, and offers a nice view over Oslo.|St Hanshaugen was originally a bare rock hill. In the 1840s, the name St Hanshaugen (\'Midsummer Hill\') came into use, as the hill was a popular place for midsummer celebrations.|In 1855, it was decided that parts of the hill were to be planted, and a large area of the hill was then turned into a park, over the next 30 years.|A park keeper\'s house, an artificial creek, and a pavilion were also added, and the park was expanded.|Through the years, a number of statues have also been placed in the park.|In 1936, an open-air café was added to Festplassen – the square on the top of the hill – which is still a popular summer café today.', 'The park was used as the starting location for a task in season 9 of Kongen Befaler.', 'The park is first seen in the \'Travel as far as possible while staring at a camera\' task, in the ninth episode of season 9 of Kongen Befaler.'),
(62, 'Kennel Farm', 'other', NULL, NULL, 'https://www.misbournevalley.co.uk/', NULL, NULL, '062_kennel_farm.jpg', '062_kennel_farm_thumb.jpg', '062_kennel_farm_2.jpg', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d361.1838017290778!2d-0.6541759472414044!3d51.67946377386779!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x487667579af6185b%3A0x17003762dde2556f!2sKennel%20Farm%2C%20Amersham%20HP7%200RJ!5e1!3m2!1sen!2suk!4v1711723062240!5m2!1sen!2suk', 'Kennel Farm is a farm estate near Little Missenden in Buckinghamshire, with over 500 acres of land.|The property features two 17th century barn conversions, a listed white dovecoat tower, stables, lakes, shooting grounds, a boathouse, streams and outbuildings.|The River Misbourne flows through the farm\'s land.', 'The farm is used as a location for pre-filmed tasks in series 17 of Taskmaster UK.', 'The farm was first seen during the contestants\' pre-series interviews, and is first used in a task during the \'Hoopla Gary before he crosses the finish line\' task, in the first episode of series 17.'),
(63, 'Stormester House (Season 8 - )', 'house', 6, 6, NULL, NULL, NULL, '063_stormester_house_vi.jpg', '063_stormester_house_vi_thumb.jpg', '063_stormester_house_vi_2.jpg', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d295.01389160797413!2d12.509377736241175!3d55.836619174211805!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x4652492d69f3ce7d%3A0x6724fbf2be06159e!2sH%C3%B8jleddet%208%2C%202840%20Holte%2C%20Denmark!5e1!3m2!1sen!2suk!4v1744011725422!5m2!1sen!2suk', 'This privately-owned house is based in the Holte municipality of Denmark.', 'The house has been used for the production of pre-filmed tasks since season 8 of Stormester.', 'The inside of the house is first seen in the \'<a href=\"/task.php?id=3398\">Turn on the bubble machine</a>\' task, in the first episode of season 8.'),
(64, 'Thorpe Park', NULL, NULL, NULL, 'https://www.thorpepark.com/', 'https://en.wikipedia.org/wiki/Thorpe_Park', 'https://www.instagram.com/thorpeparkofficial/', '064_thorpe_park.jpg', '064_thorpe_park_thumb.jpg', '064_thorpe_park_2.jpg', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d1456.7198735166783!2d-0.5146281651473384!3d51.40487931032518!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x48767778e8450561%3A0x72f8e255f2176e29!2sThorpe%20Park%20Resort!5e1!3m2!1sen!2suk!4v1726259429438!5m2!1sen!2suk', 'Thorpe Park, formerly known as Thorpe Park Resort, is a theme park located in the village of Thorpe, between the towns of Chertsey and Staines-upon-Thames in Surrey, England, 20 miles (32 km) southwest of Central London.|The park is operated by Merlin Entertainments and includes rides, themed cabins, live events, and the UK\'s tallest and fastest rollercoaster, Hyperia.', 'The theme park was used as a location for pre-filmed tasks during series 18 of Taskmaster UK.', 'The park is first seen during the \'Knock over exactly 100 cans\' task, in the first episode of series 18 of Taskmaster UK.'),
(65, 'Junior Taskmaster House', 'house', 15, 1, 'https://www.hatfield-house.co.uk/property/bush-hall-house-hatfield-hertfordshire-hatfield-park/', 'https://en.wikipedia.org/wiki/Hatfield_House', NULL, '065_junior_taskmaster_uk_house.jpg', '065_junior_taskmaster_uk_house_thumb.jpg', '065_junior_taskmaster_uk_house_2.jpg', 'https://www.google.com/maps/embed?pb=!1m17!1m12!1m3!1d186.43747725597225!2d-0.20563204527852372!3d51.775285973025994!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m2!1m1!2zNTHCsDQ2JzMxLjIiTiAwwrAxMicyMC4wIlc!5e1!3m2!1sen!2suk!4v1733490778165!5m2!1sen!2suk', 'Bush Hall House is a four-bedroom family home with extensive gardens bordering the River Lea, located in the hamlet of Mill Green in Hertfordshire.|The property is part of the Hatfield House estate, which is currently the home of Robert Gascoyne-Cecil, 7th Marquess of Salisbury.|The building itself is much larger than the one used for the original, adult version of the show, and also has larger grounds.', 'The house was used for the production of pre-filmed tasks throughout the first series of Junior Taskmaster UK.', 'The house was first seen in the \'Get the most different things in Mike’s hat\' task, in the first episode of the first series of Taskmaster UK.'),
(66, 'Painshill Park', 'other', NULL, NULL, 'https://www.painshill.co.uk/', 'https://en.wikipedia.org/wiki/Painshill', 'https://www.instagram.com/painshill/', '066_painshill_park.jpg', '066_painshill_park_thumb.jpg', '066_painshill_park_2.jpg', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3015.696485612639!2d-0.42804540285993986!3d51.32837344672658!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x4875df748017d4c7%3A0x88adbc15a4ad45e7!2sThe%20Ruined%20Abbey!5e1!3m2!1sen!2suk!4v1737728223826!5m2!1sen!2suk', 'Painshill Park is an 18th-century English landscape park set in 158 acres of land located near Cobham, in Surrey, England.|The park was designed and created between 1738 and 1773 by Charles Hamilton, and is now owned by Elmbridge Borough Council and managed by the Painshill Trust.|The landscape garden stretches along the banks of the winding River Mole on land which has a number of natural hills and valleys. The central feature is a serpentine lake of 14 acres, which has several islands and is spanned by bridges and a causeway. The water for the lake and the plantings is pumped from the River Mole by a 19th-century beam engine powered by a water wheel.|Charles Hamilton enhanced the views of the hills and lake by planting woods, avenues, and specimen trees to create vistas and separate environments, including an amphitheatre, a water meadow and an alpine valley.|As focal points in the vistas and as sympathetic elements to be discovered in the landscape, Hamilton also built a number of follies, including a crystal grotto, a Gothic \'temple\', \'ruins\' of a Gothic abbey, a Roman mausoleum, and a Gothic tower with a view of the countryside. All of these features still exist and have been restored, and a hermitage and Turkish tent have also been recreated.', 'Painshill Park was used as a location for the production of pre-filmed tasks during series 19 of Taskmaster UK.', NULL),
(67, 'Le Maître du Jeu House (Holiday Special 2024)', 'house', 13, 2, 'https://vergersdc.qc.ca/', NULL, 'https://www.instagram.com/vergercharbonneau/', '067_verger_charbonneau_cidery.jpg', '067_verger_charbonneau_cidery_thumb.jpg', '067_verger_charbonneau_cidery_2.jpg', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d423.9870950740701!2d-73.15050915105174!3d45.34749303387803!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x4cc9bb503a8bdaaf%3A0xa08ded4ae320918f!2sVergers%20%26%20Cidrerie%20Denis%20Charbonneau%20-%20Boutique%20%26%20Cr%C3%AAperie!5e1!3m2!1sen!2suk!4v1738330110986!5m2!1sen!2suk', 'Verger Charbonneau Cidery is a cidery in Mont-Saint-Grégoire near Montreal, Quebec.|Beginning as a family orchard, the business has expanded to include a creperie, a cider house, a boutique, a café-bistro, and activity and event hosting.', 'Verger Charbonneau Cidery was used for the production of pre-filmed tasks for the 2024 Holiday Special of Le Maître du Jeu.', 'The location is first seen in the \'<a href=\"/task.php?id=3866\">Blow up a balloon / Spot the difference</a>\' task.'),
(68, 'Filmhuset', 'studio', NULL, 1, 'https://www.nepsweden.com/find/studios', 'https://sv.wikipedia.org/wiki/Filmhuset', NULL, '068_filmhuset.jpg', '068_filmhuset_thumb.jpg', '068_filmhuset_2.jpg', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d603.3490348447057!2d18.102644594998726!3d59.340224858928124!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x465f9d4b7813b6ff%3A0x13468d32d27612c!2sFilmhuset!5e1!3m2!1sen!2suk!4v1738934869727!5m2!1sen!2suk', 'Filmhuset (The Film House) is located at Borgvägen 1 in Gärdet, in the north-eastern part of Stockholm\'s inner city. |The building was designed for the Swedish Film Institute by architect Peter Celsing and built between 1968 and 1970, entering use in 1971. The 140-meter-long building was designed to resemble a camera, with the lens facing north. The brutalist raw concrete design is typical of the era, and consists of concrete elements designed to look like film strips. The building is blue-labelled by the Stockholm City Museum, meaning that it is considered to have \'exceptionally high cultural and historical value\'.|The building houses recording studios and three cinemas, as well as two floors of office space. Occupants include the Swedish Film Institute, the Cinematheque, the Swedish Arts Council, Stockholm University\'s Unit for Film Studies and Centre for Fashion Studies, and various production companies. Visitors must climb a long ramp to reach the building\'s main entrance.', 'The location was used for studio filming sessions for the first three seasons of Bäst i Test, and became the studio filming location again from season 10.', 'The studio was first seen at the start of the <a href=\"/episode.php?id=94\">first episode of season 1 of Bäst i Test</a>.|The exterior of the building was first seen during the \'<a href=\"/task.php?id=967\">Arrive on time</a>\' task, during <a href=\"episode.php?id=91\">episode 6 of season 2</a>.'),
(69, 'TV-Huset', 'studio', NULL, 2, NULL, 'https://sv.wikipedia.org/wiki/TV-huset,_Stockholm', NULL, '069_tv_huset.jpg', '069_tv_huset_thumb.jpg', NULL, 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d594.8035350795718!2d18.102585647919522!3d59.33655201879199!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x465f9d4d458a2bf9%3A0xffe0a83ee1b0ccd0!2sSwedish%20Television%20(SVT)!5e1!3m2!1sen!2suk!4v1739216841098!5m2!1sen!2suk', 'TV-Huset (The TV House) is a TV studio in the Förrådsbacken neighbourhood in Stockholm that houses office and production facilities for the Swedish national public television broadcaster Sveriges Television (SVT).|The first stage of TV-huset was inaugurated in 1967. The completion of the second stage of TV-huset and its official opening was in 1969, making it one of the largest television studios in Europe at that time.', 'TV-Huset was used for filming of the studio sessions of Bäst i Test from season 4 through season 7.', 'The inside of the studio was first seen at the start of <a href=\"/episode.php?id=105\">the first episode of season 4</a>.'),
(70, 'NEP Studios', 'studio', NULL, 3, NULL, NULL, NULL, NULL, NULL, NULL, 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d297.411036753624!2d18.07366569800689!3d59.33549324926367!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x465f9d5b63b00001%3A0x23e6f327578b3418!2sHang%C3%B6v%C3%A4gen%2018%2C%20115%2041%20Stockholm%2C%20Sweden!5e1!3m2!1sen!2suk!4v1739218768725!5m2!1sen!2suk', 'NEP Studios was a TV production studio at Hangövägen 18 in Stockholm, but is now closed.', 'The location was used for filming of the studio sessions of seasons 8 and 9 of Bäst i Test.', 'The inside of the studio was first seen at the start of <a href=\"/episode.php?id=566\">the first episode of season 8</a>.'),
(71, 'Television Centre', 'studio', NULL, 1, 'https://bbcstudioworks.com/studios/', 'https://en.wikipedia.org/wiki/Television_Centre,_London', 'https://www.instagram.com/bbcstudioworks', '071_television_centre.jpg', '071_television_centre_thumb.jpg', NULL, 'https://www.google.com/maps/embed?pb=!1m17!1m12!1m3!1d1453.3537613245353!2d-0.22601414320246502!3d51.51047366225563!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m2!1m1!2zNTHCsDMwJzM3LjciTiAwwrAxMycyOS4wIlc!5e1!3m2!1sen!2suk!4v1739309636308!5m2!1sen!2suk', 'Television Centre, formerly known as BBC Television Centre, is a building complex in White City, West London, which was the headquarters of BBC Television from 1960 to 2013, when BBC Television moved to Broadcasting House.|After a refurbishment, the complex reopened in 2017 with three studios in use for TV production, operated by BBC Studioworks.', 'Television Centre was used for the filming of studio sessions for the first season of Junior Taskmaster UK.', 'The inside of the studio was first seen at the start of the <a href=\"/episode.php?id=669\">first episode of the first season</a> of Junior Taskmaster UK.'),
(72, 'Radisson Blu Plaza Hotel', 'other', NULL, NULL, 'https://www.radissonhotels.com/en-us/hotels/radisson-blu-oslo', 'http://en.wikipedia.org/wiki/Radisson_Blu_Plaza_Hotel,_Oslo', NULL, NULL, NULL, NULL, 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d292.3448046370066!2d10.755703075115239!3d59.91247053521782!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x46416e6034680b21%3A0xeb449354372e3f05!2sRadisson%20Blu%20Plaza%20Hotel%2C%20Oslo!5e1!3m2!1sen!2suk!4v1740330332273!5m2!1sen!2suk', 'The Radisson Blu Plaza Hotel in Oslo\'s city centre is Norway\'s second tallest building, at a height of 117 metres (384 ft).|The building was designed by the architectural firm White.se and completed in 1989. The hotel was officially opened in 1990 by King Olav V of Norway. In 1992, a footbridge was built between the hotel and the adjacent Oslo Spektrum arena. The hotel was remodelled in 2012.|The tower\'s foundations are concrete, and it has reflective glass facades. The uppermost floors are tapered with a steep diagonal roof on one side, leading to a sharp ridge. It also has an external glass lift, which travels up to the bar and restaurant at the top.|A lower block, three floors tall, contains the entrance, a lobby, restaurants and conference rooms. The hotel has 37 floors and 678 rooms. There are a total of 1,500 beds, 140 business rooms and 20 suites.|On the thirty-third and thirty-fourth floors (the top of the building), there are a swimming pool and a sauna.', 'The hotel\'s lobby and lift were used for the filming of the \'<a href=\"/task.php?id=1578\">Change your appearance in a lift</a>\' task in the second episode of season 2 of Kongen Befaler.', NULL),
(73, 'Nittedal Town Hall', 'other', NULL, NULL, NULL, NULL, NULL, '073_nittedal_town_hall.jpg', '073_nittedal_town_hall_thumb.jpg', '073_nittedal_town_hall_2.jpg', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d291.51961135203635!2d10.881251699895039!3d60.042909395973744!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x464177333fe49e63%3A0x64f84910648de266!2sNittedal%20municipality!5e1!3m2!1sen!2suk!4v1740340295789!5m2!1sen!2suk', 'Nittedal Town Hall is located in the municipality and city of Nittedal, in Akershus county, Norway.', 'The council chambers of the town hall were used for the production of the \'<a href=\"/task.php?id=758\">Impress the Mayor</a>\' task in season 1 episode 5 of Kongen Befaler.', NULL),
(74, 'Bogstad bathing place', 'other', NULL, NULL, NULL, 'https://en.wikipedia.org/wiki/Bogstadvannet', NULL, NULL, NULL, NULL, 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d584.333318057459!2d10.636201986971955!3d59.96958654071331!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x464173221b96bf2d%3A0x87319c0632f3b2e1!2sBogstad%20badeplass!5e1!3m2!1sen!2suk!4v1740342651514!5m2!1sen!2suk', 'Bogstad bathing place is a beach on the edge of Bogstad lake, which is located between the city of Oslo and the municipality of Bærum in Norway.', NULL, 'Bogstad bathing place was used for the production of the \'<a href=\"/task.php?id=768\">Run as far into a lake as possible</a>\' task in season 1 episode 7 of Kongen Befaler.'),
(75, 'Zinober grass pitch', 'other', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d584.0613732696194!2d10.619433177525881!3d59.984999305757945!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x464173c1ac42b007%3A0x57c4d5793daf8124!2sZinober%20gressbane%2Fundervannsbane!5e1!3m2!1sen!2suk!4v1740344615484!5m2!1sen!2suk', 'Zinober grass pitch is a public recreation area adjacent to the Sørkedal river in Sørkedalen, just outside of Oslo, Norway.|The location features two small football pitches.', 'The location was used for the production of two tasks in the first season of Kongen Befaler.', 'The pitch is first seen in the \'<a href=\"/task.php?id=773\">Draw an image using a GPS Device</a>\' task, in episode 8 of season 1 of Kongen Befaler.'),
(76, 'Babbo Collective Øvrefoss', 'other', NULL, NULL, 'https://www.babbocollective.com/babboovrefoss', NULL, NULL, '076_babbo_collective_øvrefoss.jpg', '076_babbo_collective_øvrefoss_thumb.jpg', '076_babbo_collective_øvrefoss_2.jpg', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d146.26966831796625!2d10.756681011604698!3d59.92733043246095!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x46416f69ac332b93%3A0x781159abd302d310!2sBabbo%20Collective%20%C3%98vrefoss!5e1!3m2!1sen!2suk!4v1740346059329!5m2!1sen!2suk', 'Babbo Collective Øvrefoss is a bakery and restaurant in Oslo, Norway.', 'The location was used for the production of the \'<a href=\"/task.php?id=1602\">Convince a Swede that you are the most famous contestant</a>\' task in season 2, episode 7 of Kongen Befaler.', NULL),
(77, 'Shardeloes Farm Equestrian Centre', 'other', NULL, NULL, 'https://shardeloesfarm.com/', NULL, 'https://www.instagram.com/shardeloes_farm/', NULL, NULL, NULL, 'https://www.google.com/maps/embed?pb=!1m17!1m12!1m3!1d362.1115842926669!2d-0.635239230437277!3d51.664142147191264!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m2!1m1!2zNTHCsDM5JzUxLjMiTiAwwrAzOCcwNi40Ilc!5e1!3m2!1sen!2suk!4v1740523663393!5m2!1sen!2suk', 'Shardeloes Farm Equestrian Centre is a riding school in Amersham, Buckinghamshire.', 'The Centre was used for the production of the \'<a href=\"/task.php?id=3\">Paint a horse while riding a horse</a>\' task in season 1, episode 1 of Taskmaster UK.', NULL),
(78, 'Barnes Squash Club', 'other', NULL, NULL, 'https://www.barnessquashclub.org/', NULL, NULL, NULL, NULL, NULL, 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d181.79974033991056!2d-0.24782265052813046!3d51.47773508104491!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x48760e59f67e11a1%3A0x9a7e083e1b1676fe!2s261%20Lonsdale%20Rd%2C%20London%20SW13%209QL!5e1!3m2!1sen!2suk!4v1740525391903!5m2!1sen!2suk', 'Barnes Squash Club is the Squash Section of Barnes Sports Club, which is located at 251-261 Lonsdale Rd, Barnes in South West London. The club operates two squash courts.', 'The club was used for the production of the \'<a href=\"/task.php?id=23\">Score 11 points</a>\' task in season 1, episode 4 of Taskmaster UK.', NULL),
(79, 'Ship Lane Draw Dock', 'other', NULL, NULL, NULL, NULL, NULL, '079_ship_lane_draw_dock.jpg', '079_ship_lane_draw_dock_thumb.jpg', NULL, 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d181.825508257678!2d-0.2677173790437046!3d51.47126991353885!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x48760f0000da77a1%3A0xb6dc2f6d53e03f02!2sShip%20Lane%20Draw%20Dock!5e1!3m2!1sen!2suk!4v1740526802596!5m2!1sen!2suk', 'Ship Lane Draw Dock is a draw dock on the River Thames in London. It is located directly across the River Thames from the <a href=\"/location.php?id=13\">Dukes Meadows Golf, Tennis & Ski</a> facility.', 'A section of the Thames Path adjacent to the draw dock, and a public bench on the opposite bank, were used for the production of the \'<a href=\"/task.php?id=91\">Play charades across a river</a>\' task in season 3, episode 5 of Taskmaster UK.', NULL),
(80, 'Television City', 'studio', NULL, NULL, 'https://televisioncityla.com/', 'https://en.wikipedia.org/wiki/Television_City', 'https://www.instagram.com/tvc.studios/', '080_television_city.jpg', '080_television_city_thumb.jpg', NULL, 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d1934.2475505413183!2d-118.36022136383042!3d34.07495339758428!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x80c2b9320e630255%3A0x5053bb1e0ffab4c0!2sTelevision%20City!5e1!3m2!1sen!2suk!4v1740600353177!5m2!1sen!2suk', 'Television City (also known as CBS Television City), is a television studio complex located in the Fairfax District of Los Angeles, California.|The complex currently houses a total of eight separate studios.|Designed by architect William Pereira and Charles Luckman, Television City opened in 1952 as a dedicated electronic (video) production facility, the second CBS network show factory in Southern California. Since 1961, Television City has also served as a national backup master control facility for CBS\'s television network operations.|Since its opening, numerous TV shows, specials and events have been broadcast live or recorded at Television City, including many shows not aired on CBS. It has also been the production site of several films such as the 1996 feature <em>That Thing You Do!</em>, starring Tom Hanks and Liv Tyler.|In 2018, CBS sold Television City to the real estate investment company Hackman Capital Partners while continuing to exclusively lease its space.', 'Television City was used as the studio location for the production of <a href=\"/show.php?id=7\">Taskmaster US</a>.', 'The interior of the studio was first seen at the start of the <a href=\"/episode.php?id=172\">first episode of Taskmaster US</a>.'),
(81, 'Shad Ranch', 'other', NULL, NULL, 'https://www.shadranch.com/', NULL, 'https://www.instagram.com/shad_ranch/', '081_shad_ranch.jpg', '081_shad_ranch_thumb.jpg', '081_shad_ranch_2.jpg', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d241.57067783895883!2d-118.74543274081798!3d34.14854787681169!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x80e826b5a8015555%3A0x1f7aee3e88ae4ac1!2sShad%20Ranch!5e1!3m2!1sen!2suk!4v1740603812414!5m2!1sen!2suk', 'Shad Ranch is a riding school located in Agoura Hills, California.|The facility also provides a programme of horse-based therapies.', 'The ranch was used for the production of the \'<a href=\"/task.php?id=543\">Paint a horse while riding a horse</a>\' task, in the second episode of Taskmaster US.', NULL),
(82, 'Former Westlake Village Mayor\'s Office', 'other', NULL, NULL, NULL, NULL, NULL, '082_former_westlake_village_mayors_office.jpg', '082_former_westlake_village_mayors_office_thumb.jpg', '082_former_westlake_village_mayors_office_2.jpg', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d241.5781997601638!2d-118.81434034415986!3d34.145917559273826!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x80e8248a66b90ae1%3A0xc44a7417fed7c49b!2sVillage%20Center%20Rd%2C%20Westlake%20Village%2C%20CA%2091361%2C%20USA!5e1!3m2!1sen!2suk!4v1742253818076!5m2!1sen!2suk', 'This building on Village Center Rd in Westlake Village was previously the location of the Westlake Village Mayor\'s office.|The Mayor\'s office has apparently now moved to The Westlake Village Civic Center on 31200 Oak Crest Dr, and this building has new occupants, including a children\'s music academy.', 'The location was used for the production of the \'<a href=\"/task.php?id=550\">Impress the Mayor</a>\' task, in the fourth episode of Taskmaster US.', NULL),
(83, 'Charlottenlund Fort', 'other', NULL, NULL, 'https://campingcopenhagen.dk/', 'https://da.wikipedia.org/wiki/Charlottenlund_Fort', NULL, '083_charlottenlund_fort.jpg', '083_charlottenlund_fort_thumb.jpg', '083_charlottenlund_fort_2.jpg', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d1314.3925407412048!2d12.586656874141447!3d55.74590373522521!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x46524d7863ffffff%3A0x953808f23b613359!2sCharlottenlund%20Fort!5e1!3m2!1sen!2suk!4v1740607865619!5m2!1sen!2suk', 'Charlottenlund Fort was built in Charlottenlund, near Copenhagen, Denmark, between 1883 and 1886 as a coastal battery. The fort was originally an open earthworks, but was rebuilt into a coastal fort between 1910 and 1912.|It was part of a series of sea forts that were built to protect Copenhagen from the sea, including Flakfortet and Middelgrundsfortet, both of which can be seen from Charlottenlund.|The armaments of twelve 29cm howitzer guns are still in their original positions.|The fort was closed in 1932, and is now used as a campsite and recreational area.', 'The fort was used for the production of the \'<a href=\"/task.php?id=568\">Place the exercise balls on the yoga mat</a>\' task, in the first episode of the first season of Stormester.', NULL),
(84, 'Charlottenlund Racetrack', 'other', NULL, NULL, 'https://www.travbanen.dk/', 'https://da.wikipedia.org/wiki/Charlottenlund_Travbane', 'https://www.instagram.com/charlottenlundtravbane/', '084_charlottenlund_racetrack.jpg', '084_charlottenlund_racetrack_thumb.jpg', NULL, 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d1314.0881751277072!2d12.58686352285675!3d55.75493824171417!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x46524d9e153953eb%3A0xc4119bb89eaab676!2sTraverbanevej%2010%2C%202920%20Charlottenlund%2C%20Denmark!5e1!3m2!1sen!2suk!4v1740609854400!5m2!1sen!2suk', 'Charlottenlund Racetrack (Charlottenlund Travbane) is a harness racing track in the town of Charlottenlund, near Copenhagen, Denmark.|The racetrack, nicknamed Lunden, was established in 1891 by the Danish Trotting Club (Det Danske Travselskab).|The annual major events held at Charlottenlund Racetrack are the Danish Trotting Derby and the international Copenhagen Cup.', 'The track, onto which the <a href=\"/location.php?id=32\">house used for the first season of Stormester</a> backs, was used for the production of some tasks during that season.', 'The location was first seen in the \'<a href=\"/task.php?id=581\">Paint a horse while riding a horse</a>\' task in season 1, episode 4 of Stormester.'),
(85, 'Garden of the Gylfesvej 3 summer house', 'other', NULL, NULL, NULL, NULL, NULL, '085_garden_of_the_gylfesvej_3_summer_house.jpg', '085_garden_of_the_gylfesvej_3_summer_house_thumb.jpg', '085_garden_of_the_gylfesvej_3_summer_house_2.jpg', 'https://www.google.com/maps/embed?pb=!1m17!1m12!1m3!1d326.53665824301953!2d12.558219893100606!3d55.990326463068634!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m2!1m1!2zNTXCsDU5JzI0LjkiTiAxMsKwMzMnMjkuOCJF!5e1!3m2!1sen!2suk!4v1741004257608!5m2!1sen!2suk', 'The summer house at Gylfesvej 3 in Espergærde, Denmark, was built in 1880 and contains eight rooms, a kitchen, and two bathrooms. The property is located in Helsingør Municipality and belongs to the Espergærde school district.', 'The sloped garden of the summer house was used for the production of two Stormester tasks, in season 2 and the 2019 Christmas Special.', 'The location was first seen in the \'<a href=\"/task.php?id=611\">Knock over the fewest bowling pins</a>\' task, in season 2, episode 2 of Stormester.'),
(86, 'Rødovre Skating Arena', 'other', NULL, NULL, NULL, 'https://da.wikipedia.org/wiki/R%C3%B8dovre_Sk%C3%B8jte_Arena', NULL, '086_rødovre_skating_arena.jpg', '086_rødovre_skating_arena_thumb.jpg', '086_rødovre_skating_arena_2.jpg', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d658.2996913662979!2d12.44125243532595!3d55.68036883129122!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x4652510057af07b7%3A0x5868dbeb2cf96149!2zUsO4ZG92cmUgU2vDuGp0ZWFyZW5h!5e1!3m2!1sen!2suk!4v1741039217708!5m2!1sen!2suk', 'Rødovre Skating Arena is an ice skating rink in Rødovre, Copenhagen, Denmark. The rink, which was opened in 1995, is home to both Rødovre Skating and Ice Hockey Club, and the Danish ice hockey league team the Rødovre Mighty Bulls.|In 2018, the rink officially changed its name to Rødovre Centrum Arena as a result of a name sponsorship from the Rødovre Centrum shopping centre. In 2024, the Danish moving company Holger Danske Flytteforretning took over sponsorship, and the rink became known as Holger Danske Arena.', 'The location was used for the filming of the \'<a href=\"/task.php?id=629\">Remove the beach balls in the correct order</a>\' task, in season 2, episode 5 of Stormester.', NULL),
(87, 'Gentofte Athletics Track / Copenhagen Towers Training Field', 'other', NULL, NULL, 'https://www.gentofte-atletik.dk/', NULL, 'https://www.instagram.com/gentofteatletik/', '087_gentofte_athletics_track.jpg', '087_gentofte_athletics_track_thumb.jpg', '087_gentofte_athletics_track_2.jpg', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d656.985827851238!2d12.52267359307168!3d55.758396639534396!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x46524e09ec9c071b%3A0x855c1c7026e2c65a!2sGentofte%20Atletik!5e1!3m2!1sen!2suk!4v1741040831853!5m2!1sen!2suk', 'Gentofte Athletics Track is an athletics club in Gentofte, near Copenhagen, Denmark.|In addition to the athletics facilities, the location features a multi-purposes grass pitch, upon which football, rugby, and American football are played.|Next to the athletics track, there is also a separate training field for the Copenhagen Towers American football team.', 'The location was used for the production of the \'<a href=\"/task.php?id=667\">Score a goal from the greatest distance</a>\' task, in season 3, episode 5 of Stormester.', NULL),
(88, 'Embassy of Pakistan', 'other', NULL, NULL, 'https://www.pakistanembassy.dk/', NULL, 'https://www.instagram.com/pakindenmark/', '088_embassy_of_pakistan.jpg', '088_embassy_of_pakistan_thumb.jpg', NULL, 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d164.32833026745956!2d12.556785814455802!3d55.73895422643448!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x46525275e23594dd%3A0xf2b184f63d2475f0!2sEmbassy%20of%20Pakistan!5e1!3m2!1sen!2suk!4v1741047634394!5m2!1sen!2suk', 'The Embassy of Pakistan in Denmark is located in Hellerup, Copenhagen.', 'The Embassy is used for the production of the \'<a href=\"/task.php?id=693\">Impress the Ambassador</a>\' task, in season 4, episode 1 of Stormester.', NULL),
(89, 'Lappis Student Residence', 'other', NULL, NULL, NULL, NULL, NULL, '089_lappis_student_residence.jpg', '089_lappis_student_residence_thumb.jpg', NULL, 'https://www.google.com/maps/embed?pb=!1m17!1m12!1m3!1d297.4372029336207!2d18.063108661794306!3d59.37028986325401!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m2!1m1!2zNTnCsDIyJzEzLjAiTiAxOMKwMDMnNDcuNCJF!5e1!3m2!1sen!2suk!4v1741050314515!5m2!1sen!2suk', 'Lappis Student Residence is a student dormitory complex close to Stockholm University\'s Frescati Campus in Stockholm, Sweden.', 'The location was used for the production of the \'<a href=\"/task.php?id=993\">Return to the house wearing a hat</a>\' task, in season 3, episode 1 of Bäst i Test.', NULL),
(90, 'National Museum of Natural History', 'other', NULL, NULL, 'https://www.nrm.se/', 'https://sv.wikipedia.org/wiki/Naturhistoriska_riksmuseet', 'https://www.instagram.com/naturhistoriska/', '090_national_museum_of_natural_history.jpg', '090_national_museum_of_natural_history_thumb.jpg', NULL, 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d1189.7915177011016!2d18.052823891871924!3d59.369072128845666!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x465f9d06c299a63d%3A0xe5f99fa024a7bfd!2sMuseum%20of%20Natural%20History!5e1!3m2!1sen!2suk!4v1741051125666!5m2!1sen!2suk', 'The National Museum of Natural History is a biological and geological museum in Stockholm, Sweden, established in 1819.|The current museum building, located within the Royal National City Park, was designed by architect Axel Anderberg and opened in 1916.|The museum is Sweden\'s largest museum complex, and also houses Cosmonova (a planetarium and domed IMAX cinema).', 'The museum was used for the production of the \'<a href=\"/task.php?id=1125\">Find Trausti</a>\' task, in season 4, episode 5 of Bäst i Test.', NULL),
(91, 'Farsta Strand Park', 'other', NULL, NULL, NULL, NULL, NULL, '091_farsta_strand_park.jpg', '091_farsta_strand_park_thumb.jpg', NULL, 'https://www.google.com/maps/embed?pb=!1m10!1m8!1m3!1d596.6285884224425!2d18.093191015838535!3d59.232263532811736!3m2!1i1024!2i768!4f13.1!5e1!3m2!1sen!2suk!4v1741812169249!5m2!1sen!2suk', 'The Farsta Strand park is an open area of public land near to the Vilohemmet property used for the production of Bäst i Test since season 8.', 'The park has been used for the production of some outdoor tasks since season 8 of Bäst i Test.', NULL),
(92, 'Farsta Strand Boardwalk', 'other', NULL, NULL, NULL, NULL, NULL, '092_farsta_boardwalk.jpg', '092_farsta_boardwalk_thumb.jpg', NULL, 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d298.6282292087428!2d18.08713145459354!3d59.2343495741106!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x465f7988d28511f3%3A0x21343d61c5b3fbcf!2sBadbrygga%20%22Enskilds%22!5e1!3m2!1sen!2suk!4v1741997102422!5m2!1sen!2suk', 'This wooden boardwalk in Farsta Strand, near to the Vilohemmet property used as the house since season 8 of Bäst i Test, runs along the edge of Magelungen, a lake on the border between the municipalities of Huddinge and Stockholm.|The Badbrygga Enskilds (Individuality bathing pier) is accessible from the boardwalk.', 'The boardwalk has occasionally been used for the production of tasks since season 9 of Bäst i Test.', 'The boardwalk was first seen in the \'<a href=\"/task.php?id=3527\">Deliver 29 roses to David’s vase</a>\' task, in season 9, episode 4.'),
(93, 'Lilla Sjötullsbron', 'other', NULL, NULL, NULL, 'https://sv.wikipedia.org/wiki/Lilla_Sj%C3%B6tullsbron', NULL, '093_lilla_sjötullsbron.jpg', '093_lilla_sjötullsbron_thumb.jpg', NULL, 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d301.4642588542415!2d18.14674919811177!3d59.32659823151416!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x465f836e96c11d39%3A0xfb88f5b5d79a7eaf!2sLilla%20Sj%C3%B6tullsbron!5e1!3m2!1sen!2suk!4v1741873643831!5m2!1sen!2suk', 'Lilla Sjötullsbron is a pedestrian and bicycle bridge over the Djurgårdsbrunn Canal on Djurgården in Stockholm, Sweden.|The small arch bridge was built in 1965 in concrete, and is 3.8 metres wide and 32 metres long.|The bridge is named after the canal\'s toll building, Lilla Sjötullen, which was built in the 1830s and is located right next to it.', 'The bridge was used for the production of a couple of tasks in season 4 of Bäst i Test.', 'The bridge was first seen in the \'<a href=\"/task.php?id=1126\">High-five David second</a>\' task, in season 4, episode 5.'),
(94, 'Biskopsudden', 'other', NULL, NULL, NULL, 'https://sv.wikipedia.org/wiki/Biskopsudden', NULL, '094_biskopsudden.jpg', '094_biskopsudden_thumb.jpg', NULL, 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d301.5188580314856!2d18.122533861451714!3d59.32044312213472!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x465f82a7373bbf85%3A0xf863871aa538a694!2sBiskopsudden!5e1!3m2!1sen!2suk!4v1741874640765!5m2!1sen!2suk', 'Biskopsudden (Bishop\'s Cape) is a cape on the island and district of South Djurgården in Stockholm, Sweden.|The cape is the location of a marina and open parkland, featuring an open pavillion with a view of the Stockholm inlet.', 'The location was used for the production of the \'<a href=\"/task.php?id=1158\">Say hello to David from as far away as possible</a>\' task, in season 4 of Bäst i Test.', NULL),
(95, 'Cockatoo Island (Wareamah)', 'other', 14, 1, 'https://www.cockatooisland.gov.au/', 'https://en.wikipedia.org/wiki/Cockatoo_Island', NULL, '095_cockatoo_island_wareamah.jpg', '095_cockatoo_island_wareamah_thumb.jpg', '095_cockatoo_island_wareamah_2.jpg', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3490.5343218680964!2d151.17057866387557!3d-33.84753376569863!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x6b12afa4e11383d7%3A0xf017d68f9f0ab30!2sCockatoo%20Island!5e1!3m2!1sen!2suk!4v1743869785115!5m2!1sen!2suk', 'Cockatoo Island (called Wareamah by Indigenous Australians who inhabited the land prior to European settlement) is an island located at the confluence of the Parramatta River and Lane Cove River in Sydney Harbour, Australia.|Between 1839 and 1869, Cockatoo Island was operated as a convict penal establishment, primarily as a place of secondary punishment for convicts who had re-offended in the colonies.|Between 1857 and 1991, Cockatoo Island was also the site of one of Australia\'s biggest shipyards, and the first of its two dry docks was built by convicts.|Cockatoo Island has been managed by the Sydney Harbour Federation Trust since 2001, and has hosted a number of major arts events since 2005. In 2010, UNESCO proclaimed the island to be a World Heritage Site.', 'The island was used for the production of some pre-filmed tasks during the fourth season of Taskmaster AU.', 'The island is first seen during the \'<a href=\"/task.php?id=4064\">Move a box over the red line</a>\' task, in the second episode of season 4.'),
(96, 'Municipal Athletic Complex Carla Sacramento', 'other', 11, 1, 'https://www.cm-seixal.pt/equipamento/complexo-municipal-de-atletismo-carla-sacramento', NULL, NULL, NULL, NULL, NULL, 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d820.827780887656!2d-9.137031786403798!3d38.62787318718997!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0xd194a785553e38f%3A0xc452a3e4110abe2c!2sMunicipal%20Athletic%20Complex%20Carla%20Sacramento!5e1!3m2!1sen!2suk!4v1748260213236!5m2!1sen!2suk', 'The Complexo Municipal de Atletismo Carla Sacramento (Municipal Athletic Complex Carla Sacramento) is an athletics facility in Amora, Portugal, equipped for a range of track and field sports.', 'The complex was used for the filming of a task in season 5 of Taskmaster PT.', NULL),
(97, 'Espoonlahti Sports Park', 'other', 9, 1, 'https://www.espoo.fi/fi/liikunta-ja-luonto/ulkoliikuntapaikat/urheilupuistot/espoonlahden-urheilupuisto', NULL, NULL, NULL, NULL, NULL, 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d522.4093352105043!2d24.659944698214524!3d60.14447762056306!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x468df5a4134c83b5%3A0xc3a3f4dc39bec1a2!2sEspoonlahti%20Artificial%20Turf%20Field%203!5e1!3m2!1sen!2suk!4v1749666890419!5m2!1sen!2suk', 'Espoonlahden urheilupuisto (Espoonlahti Sports Park) is a sports park in Espoo, Finland, featuring three artificial turf pitches, a baseball field, basketball and volleyball courts, a skate park, a cycling track, and athletic track and field facilities.', 'The location is used for the production of at least one task during season 6 of Suurmestari.', 'The location is first seen during the \'Find the squirrel\' task in season 6, episode 4, in which its third artificial turf pitch is used.'),
(98, 'Studio Cinépool', 'studio', 13, 2, 'https://www.cinepool.ca/', NULL, NULL, NULL, NULL, NULL, 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d737.2844955315513!2d-73.63868278601966!3d45.436030101983725!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x4cc911318d97dad3%3A0x4e9628dba3c1d98f!2sGrand%C3%A9%20Studios%20-%20Cinepool!5e1!3m2!1sen!2suk!4v1750529538346!5m2!1sen!2suk', 'Studio Cinépool is a TV filming studio facility in Lasalle, Quebec.', 'The studio has been used for the production of the live studio sessions of Le Maître du Jeu since season 2.', NULL),
(99, 'Rialto Theatre', 'studio', 13, 1, 'https://www.theatrerialto.ca/', 'https://en.wikipedia.org/wiki/Rialto_Theatre_(Montreal)', NULL, NULL, NULL, NULL, 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d368.06922570215164!2d-73.60493946640077!3d45.52368004480981!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x4cc91979b5c90b2d%3A0x7b2509bbe74a11aa!2sRialto%20Theatre!5e1!3m2!1sen!2suk!4v1750530467796!5m2!1sen!2suk', 'The Rialto Theatre is a former movie palace located on Park Avenue in Montreal, Quebec, Canada. It is designated as a National Historic Site of Canada.|Built in 1923-1924, the Rialto was inspired by the Napoleon III style Paris Opera House.|The Rialto operated as a cinema until the 1990s, and has undergone many changes since 2000. It was sold to its current owners in 2010, who have since attempted to protect the theatre and restore its unique architecture.', 'The theatre was used for the production of the live studio sessions of the first season of Le Maître du Jeu.', NULL),
(100, 'Studio West', 'studio', 8, 1, 'https://www.studiowest.co.nz/', 'https://en.wikipedia.org/wiki/Studio_West_(film_studio)', NULL, NULL, NULL, NULL, 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d420.08150218690304!2d174.63691292890212!3d-36.90626182111442!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x6d0d419079e33093%3A0x7d0f671abad2357c!2s16%20Waikaukau%20Road%2C%20Glen%20Eden%2C%20Auckland%200602%2C%20New%20Zealand!5e1!3m2!1sen!2suk!4v1751049553981!5m2!1sen!2suk', 'Studio West is a motion picture and television production facility in West Auckland, New Zealand.|Opening in 1996, the studio grew in the 2000s after Auckland Regional Economic Development Strategy promoted the screen production industry in Auckland as a major driver of economic growth.|The studio became the primary filming location for the US TV show <em>Power Rangers</em> in 2002. It was also used for the production of numerous other films and TV shows, including <em>The Vintner\'s Luck</em>, <em>Under the Mountain</em>, <em>Yogi Bear</em>, <em>Young Hercules</em>, and <em>Xena: Warrior Princess</em>.|It grew further due to an expansion project launched in 2019. After being put on hold due to the Covid-19 pandemic, the new studio opened in 2022, becoming the largest purpose-built sound stage in Auckland.', 'The studio was used for the production of Taskmaster NZ\'s live studio sessions during seasons 3 and 6.', NULL),
(101, 'Fremantle Studios Portugal', 'studio', 11, 1, NULL, NULL, NULL, NULL, NULL, NULL, 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d204.88283731290076!2d-8.941585627932723!3d38.74098049762131!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0xd193bca479914c5%3A0x239942ac7ea36ade!2sEST%C3%9ADIOS%20FREMANTLE%20PORTUGAL!5e1!3m2!1sen!2suk!4v1751520031410!5m2!1sen!2suk', 'Fremantle Studios Portugal is a TV studio in Alcochete, Portugal, run by the multi-national production and distribution company Fremantle.', 'The studio has been used for the production of the live studio sessions of Taskmaster PT since season 1.', NULL),
(102, 'Sandown Park Racecourse', 'other', 1, 1, 'https://www.thejockeyclub.co.uk/sandown/', 'https://en.wikipedia.org/wiki/Sandown_Park_Racecourse', 'https://www.instagram.com/sandownparkracecourse/', NULL, NULL, NULL, 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d1477.1711844268655!2d-0.36303664773013977!3d51.37368330721127!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x48760ac5f402c7e1%3A0x795d3a0ac75ae452!2sSandown%20Park%20Racecourse!5e1!3m2!1sen!2suk!4v1751632511301!5m2!1sen!2suk', 'Sandown Park is a horse racing course and leisure venue in Esher, Surrey, England, located in the outer suburbs of London.|The course hosts 5 Grade One National Hunt races and one Group 1 flat race, the Eclipse Stakes.|It also hosts many non-racing events such as trade shows, wedding fairs, toy fairs, car shows and auctions, property shows, concerts, and even some private events.', 'The course is used for the production of off-site tasks during series 20 of Taskmaster UK.', NULL),
(103, 'Colleruphus Scouts Cabin', 'other', 6, 1, 'https://colleruphus.bookhus.dk/', NULL, NULL, NULL, NULL, NULL, 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d294.6524547504262!2d12.49622321334296!3d55.83619317255526!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x46524ed5344f4033%3A0x30f5b8b5f8340812!2sColleruphus%20Det%20Danske%20Spejderkorps!5e1!3m2!1sen!2suk!4v1752061267863!5m2!1sen!2suk', 'Colleruphus is the largest of eight cabins owned by the Danske Spejderkorps (Danish Scout Corps), located in Holte, near Copenhagen in Denmark.', 'The grounds of the hut were used for the production of a task in season 9, episode 5 of Stormester.', NULL),
(104, 'Søllerød Golf Club', 'other', 6, 1, 'https://sollerodgolf.dk', NULL, NULL, NULL, NULL, NULL, 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d590.1405074076396!2d12.513414191165376!3d55.82918997308944!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x46524ecc1f7ea259%3A0x45270fc989b512df!2zU8O4bGxlcsO4ZCBHb2xma2x1Yg!5e1!3m2!1sen!2suk!4v1754090627681!5m2!1sen!2suk', 'Søllerød Golf Club is an 18-hole golf course in the Holte area of Copenhagen, Denmark.', 'The location was used for the production of the \'<a href=\"/task.php?id=4335\">Get the ball in the hole without touching it</a>\' task, during season 9 of Stormester.', NULL),
(105, 'Rainbow\'s End', 'other', 8, 1, 'https://rainbowsend.co.nz/', 'https://en.wikipedia.org/wiki/Rainbow%27s_End_(theme_park)', NULL, NULL, NULL, NULL, 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d839.1883491427486!2d174.88259599108315!3d-36.99467742225397!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x6d0d4dbdfda5c73b%3A0xd323475816aecab3!2sRainbow&#39;s%20End!5e1!3m2!1sen!2suk!4v1755947672861!5m2!1sen!2suk', 'Rainbow\'s End is a theme park located in Auckland, New Zealand, featuring more than 20 rides and attractions on a 23 acre site.', 'The location was used for the production of some tasks during season 6 of Taskmaster NZ.', NULL),
(106, 'Enskede Racket Hall', 'other', 3, 1, 'https://www.enskederackethall.se/', NULL, 'https://www.instagram.com/enskederackethall', NULL, NULL, NULL, 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d1073.2450642794215!2d18.05718134769439!3d59.28775997229134!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x465f778418c549bd%3A0xa83d67baa7cc9b03!2sEnskede%20Rackethall!5e1!3m2!1sen!2suk!4v1756028778029!5m2!1sen!2suk', 'Enskede Racket Hall is one of Stockholm\'s largest and most complete racket halls, offering facilities for table tennis, badminton, squash, tennis, racketlon, and pickleball, plus a well-equipped gym.|It also has a shop offering equipment for purchase or rental, a café which serves breakfast and lunch on weekdays, and a conference room for up to 15 people.|The facility is owned by Enskede Lawn Tennis Club and the Stockholm Badminton Association.', 'The location was used for the production of a task during season 9 of Bäst i Test.', NULL),
(107, 'The Old Orangery', 'other', 3, 1, 'https://gamlaorangeriet.se/', NULL, 'https://www.instagram.com/gamlaorangeriet/', NULL, NULL, NULL, 'https://www.google.com/maps/embed?pb=!1m14!1m8!1m3!1d297.44174671095243!2d18.045841995055707!3d59.36977161304775!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x465f9da9ee525ed9%3A0xfef8b3710c28a072!2sOld%20Orangery!5e1!3m2!1sen!2suk!4v1756050949361!5m2!1sen!2suk', 'The Old Orangery is a restaurant and event venue located in Stockholm on the site of a former orangery (a conservatory where orange trees are grown), founded in 1926.', 'The location was used for the production of a task for the  first season of Bäst i Test.', NULL);
