
-- --------------------------------------------------------

--
-- Table structure for table `locations`
--

CREATE TABLE `locations` (
  `id` smallint(3) UNSIGNED NOT NULL COMMENT 'Unique identifier',
  `name` varchar(256) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT 'Display name',
  `category` enum('house','studio','other') COLLATE utf8_unicode_ci DEFAULT NULL COMMENT 'Location category',
  `primary_show_id` tinyint(2) UNSIGNED DEFAULT NULL COMMENT 'ID of the show which first used the location.',
  `sort_order` tinyint(2) UNSIGNED DEFAULT NULL COMMENT 'Sort order for location within its show and category.',
  `website` varchar(256) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT 'Location website URL',
  `wikipedia` varchar(256) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT 'Location Wikipedia page URL',
  `instagram` varchar(256) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT 'Location Instagram account.',
  `primary_photo` varchar(256) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT 'Primary image URL',
  `primary_photo_thumbnail` varchar(256) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT 'Smaller version of primary photo.',
  `secondary_photo` varchar(256) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT 'Secondary image URL',
  `map_embed_link` varchar(1024) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT 'Google map embed link',
  `description` varchar(4096) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT 'Description (use pipe characters for paragraph breaks).',
  `taskmaster_connection` varchar(512) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT 'Note on how the location is ocnnected to Taskmaster.',
  `first_appearance` varchar(512) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT 'Description of the location''s first appearance on the show.'
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

